import subprocess,time
def send_literal(s):
    for ch in s:
        if ch=='\n':
            subprocess.run(["tmux","send-keys","-t","gt","Enter"])
        else:
            subprocess.run(["tmux","send-keys","-t","gt","-l",ch])
        time.sleep(0.02)
