def cap_metrics():
    out=subprocess.check_output(["tmux","capture-pane","-t","gt","-p"]).decode()
    for l in out.splitlines():
        if "Metrics" in l or "WPM:" in l or "Progress" in l or "%" in l:
            print(l.strip())
