{"command":"cat > src/main.rs <<'RS'
use clap::{Arg, ArgAction, Command};
use std::io::Write;
use std::path::PathBuf;
use std::sync::Mutex;

pub mod db;
pub mod model;
pub mod extract;
pub mod cache;
pub mod app;

pub struct AppError {
    pub message: String,
    pub causes: Vec<String>,
}
impl AppError {
    pub fn new(message: impl Into<String>) -> Self { Self { message: message.into(), causes: vec![] } }
    pub fn with_causes(message: impl Into<String>, causes: Vec<String>) -> Self { Self { message: message.into(), causes } }
}
impl std::fmt::Display for AppError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { write!(f, "{}", self.message) }
}
impl From<std::io::Error> for AppError {
    fn from(e: std::io::Error) -> Self { Self::new(e.to_string()) }
}
pub type AppResult<T> = Result<T, AppError>;

// ---------------- logging ----------------
pub struct Logger { file: std::fs::File, pub dir: PathBuf }
pub static LOGGER: std::sync::OnceLock<Mutex<Logger>> = std::sync::OnceLock::new();

pub fn gittype_dir() -> PathBuf {
    let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("."));
    home.join(".gittype")
}

pub fn init_logging() {
    let dir = gittype_dir().join("logs");
    let _ = std::fs::create_dir_all(&dir);
    let now = chrono::Local::now();
    let filename = format!("gittype_{}.log", now.format("%Y%m%d_%H%M%S"));
    let path = dir.join(&filename);
    if let Ok(file) = std::fs::OpenOptions::new().create(true).append(true).open(&path) {
        let _ = LOGGER.set(Mutex::new(Logger { file, dir: dir.clone() }));
        log_info("gittype::infrastructure::logging", &format!("GitType logging initialized, logs saved to: {}", dir.display()));
    }
}

pub fn log_line(level: &str, module: &str, msg: &str) {
    if let Some(logger) = LOGGER.get() {
        if let Ok(mut guard) = logger.lock() {
            let ts = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
            let _ = writeln!(guard.file, "{} [{}] {} - {}", ts, level, module, msg);
            let _ = guard.file.flush();
        }
    }
}
pub fn log_info(module: &str, msg: &str) { log_line("INFO", module, msg); }
pub fn log_warn(module: &str, msg: &str) { log_line("WARN", module, msg); }
pub fn log_error(module: &str, msg: &str) { log_line("ERROR", module, msg); }

pub fn handle_fatal(err: AppError) -> ! {
    // write error details file to cwd
    let now_utc = chrono::Utc::now();
    let filename = format!("gittype_error_{}.log", now_utc.format("%Y%m%d_%H%M%S"));
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let args: Vec<String> = std::env::args().collect();
    let exe = std::env::current_exe().unwrap_or_else(|_| PathBuf::from(args.get(0).cloned().unwrap_or_default()));
    let mut block = String::new();
    block.push_str(&format!("ERROR OCCURRED AT: {} UTC\n", now_utc.format("%Y-%m-%d %H:%M:%S")));
    block.push_str("ERROR TYPE: \"gittype::domain::error::GitTypeError\"\n");
    block.push_str(&format!("ERROR MESSAGE: {}\n", err.message));
    for (i, c) in err.causes.iter().enumerate() {
        block.push_str(&format!("CAUSED BY (level {}): {}\n", i + 1, c));
    }
    block.push_str(&format!("EXECUTABLE: \"{}\"\n", exe.display()));
    block.push_str(&format!("WORKING_DIR: \"{}\"\n", cwd.display()));
    block.push_str(&format!("COMMAND_ARGS: {:?}\n", args));
    block.push_str(&format!("OS: {}\n", std::env::consts::OS));
    block.push_str(&format!("ARCH: {}\n", std::env::consts::ARCH));
    // append to file
    if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(&filename) {
        let _ = write!(f, "{}\n", block);
    }
    log_error("gittype::infrastructure::logging", &format!("APPLICATION ERROR:\n{}", block.trim_end()));
    eprintln!("💾 Error details written to: {}", filename);
    eprintln!("Error: {}", err.message);
    if !err.causes.is_empty() {
        eprintln!();
        eprintln!("Caused by:");
        for (i, c) in err.causes.iter().enumerate() {
            eprintln!("    {}: {}", i, c);
        }
    }
    std::process::exit(1);
}

