impl AppError {
    pub fn new(message: impl Into<String>) -> Self { Self { message: message.into(), causes: vec![] } }
    pub fn with_causes(message: impl Into<String>, causes: Vec<String>) -> Self { Self { message: message.into(), causes } }
}
impl std::fmt::Display for AppError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { write!(f, "{}", self.message) }
}
impl From<std::io::Error> for AppError {
    fn from(e: std::io::Error) -> Self { Self::new(e.to_string()) }
}
pub type AppResult<T> = Result<T, AppError>;

// ---------------- logging ----------------
pub struct Logger { file: std::fs::File, pub dir: PathBuf }
pub static LOGGER: std::sync::OnceLock<Mutex<Logger>> = std::sync::OnceLock::new();

pub fn gittype_dir() -> PathBuf {
    let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("."));
