}

pub fn init_logging() {
    let dir = gittype_dir().join("logs");
    let _ = std::fs::create_dir_all(&dir);
    let now = chrono::Local::now();
    let filename = format!("gittype_{}.log", now.format("%Y%m%d_%H%M%S"));
    let path = dir.join(&filename);
    if let Ok(file) = std::fs::OpenOptions::new().create(true).append(true).open(&path) {
        let _ = LOGGER.set(Mutex::new(Logger { file, dir: dir.clone() }));
        log_info("gittype::infrastructure::logging", &format!("GitType logging initialized, logs saved to: {}", dir.display()));
    }
}

pub fn log_line(level: &str, module: &str, msg: &str) {
    if let Some(logger) = LOGGER.get() {
        if let Ok(mut guard) = logger.lock() {
            let ts = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
            let _ = writeln!(guard.file, "{} [{}] {} - {}", ts, level, module, msg);
            let _ = guard.file.flush();
        }
    }
