pub fn log_warn(module: &str, msg: &str) { log_line("WARN", module, msg); }
pub fn log_error(module: &str, msg: &str) { log_line("ERROR", module, msg); }

pub fn handle_fatal(err: AppError) -> ! {
    // write error details file to cwd
    let now_utc = chrono::Utc::now();
    let filename = format!("gittype_error_{}.log", now_utc.format("%Y%m%d_%H%M%S"));
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let args: Vec<String> = std::env::args().collect();
    let exe = std::env::current_exe().unwrap_or_else(|_| PathBuf::from(args.get(0).cloned().unwrap_or_default()));
    let mut block = String::new();
    block.push_str(&format!("ERROR OCCURRED AT: {} UTC\n", now_utc.format("%Y-%m-%d %H:%M:%S")));
    block.push_str("ERROR TYPE: \"gittype::domain::error::GitTypeError\"\n");
    block.push_str(&format!("ERROR MESSAGE: {}\n", err.message));
    for (i, c) in err.causes.iter().enumerate() {
        block.push_str(&format!("CAUSED BY (level {}): {}\n", i + 1, c));
    }
    block.push_str(&format!("EXECUTABLE: \"{}\"\n", exe.display()));
    block.push_str(&format!("WORKING_DIR: \"{}\"\n", cwd.display()));
    block.push_str(&format!("COMMAND_ARGS: {:?}\n", args));
    block.push_str(&format!("OS: {}\n", std::env::consts::OS));
    block.push_str(&format!("ARCH: {}\n", std::env::consts::ARCH));
    // append to file
    if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(&filename) {
        let _ = write!(f, "{}\n", block);
    }
    log_error("gittype::infrastructure::logging", &format!("APPLICATION ERROR:\n{}", block.trim_end()));
    eprintln!("💾 Error details written to: {}", filename);
    eprintln!("Error: {}", err.message);
    if !err.causes.is_empty() {
        eprintln!();
        eprintln!("Caused by:");
        for (i, c) in err.causes.iter().enumerate() {
            eprintln!("    {}: {}", i, c);
        }
    }
    std::process::exit(1);
}

