pub enum Parsed {
    Game { repo_path: Option<String>, repo_spec: Option<String>, langs: Option<String> },
    History,
    Stats,
    Export { format: String, output: Option<String> },
    CacheStats,
    CacheClear,
    CacheList,
    RepoList,
    RepoClear { force: bool },
    RepoPlay,
    Trending { language: Option<String>, repo_name: Option<String>, period: String },
}

fn main() {
    let cmd = build_cli();
    let matches = cmd.try_get_matches();
    let matches = match matches {
        Ok(m) => m,
        Err(e) => { e.exit(); }
    };
    // dispatch based on subcommand
    let parsed: Parsed = if let Some((sub, sub_m)) = matches.subcommand() {
        match sub {
            "history" => Parsed::History,
            "stats" => Parsed::Stats,
            "export" => Parsed::Export {
                format: sub_m.get_one::<String>("format").cloned().unwrap_or_else(|| "json".to_string()),
                output: sub_m.get_one::<String>("output").cloned(),
            },
            "cache" => {
                match sub_m.subcommand() {
                    Some(("stats", _)) => Parsed::CacheStats,
                    Some(("clear", _)) => Parsed::CacheClear,
                    Some(("list", _)) => Parsed::CacheList,
                    _ => Parsed::CacheStats,
                }
            }
            "repo" => {
                match sub_m.subcommand() {
                    Some(("list", _)) => Parsed::RepoList,
                    Some(("clear", cm)) => Parsed::RepoClear { force: cm.get_flag("force") },
                    Some(("play", _)) => Parsed::RepoPlay,
                    _ => Parsed::RepoList,
                }
            }
            "trending" => Parsed::Trending {
                language: sub_m.get_one::<String>("LANGUAGE").cloned(),
                repo_name: sub_m.get_one::<String>("REPO_NAME").cloned(),
                period: sub_m.get_one::<String>("period").cloned().unwrap_or_else(|| "daily".to_string()),
            },
            _ => Parsed::Game { repo_path: None, repo_spec: None, langs: None },
        }
    } else {
        Parsed::Game {
            repo_path: matches.get_one::<String>("REPO_PATH").cloned(),
            repo_spec: matches.get_one::<String>("repo").cloned(),
            langs: matches.get_one::<String>("langs").cloned(),
        }
    };

    init_logging();

    let result: AppResult<()> = match parsed {
        Parsed::History => {
            eprintln!("❌ History command is not yet implemented");
            eprintln!("💡 This feature is planned for a future release");
            std::process::exit(1);
        }
        Parsed::Stats => {
            eprintln!("❌ Stats command is not yet implemented");
            eprintln!("💡 This feature is planned for a future release");
            std::process::exit(1);
        }
        Parsed::Export { format, output } => {
            eprintln!("❌ Export command is not yet implemented");
            eprintln!("💡 Requested format: {}", format);
            if let Some(out) = output { eprintln!("💡 Requested output: {}", out); }
            eprintln!("💡 This feature is planned for a future release");
            std::process::exit(1);
        }
        Parsed::CacheStats => cache::cache_stats(),
        Parsed::CacheClear => cache::cache_clear(),
        Parsed::CacheList => cache::cache_list(),
        Parsed::RepoClear { force } => app::repo_clear(force),
        Parsed::RepoList => app::run_repo_list(),
        Parsed::RepoPlay => app::run_repo_play(),
        Parsed::Trending { language, repo_name, period } => app::run_trending(language, repo_name, period),
        Parsed::Game { repo_path, repo_spec, langs } => app::run_game(repo_path, repo_spec, langs),
    };
    if let Err(e) = result { handle_fatal(e); }
}
