pub fn validate_langs(input: &str) -> Result<Vec<Language>, Vec<String>> {
    let mut out = Vec::new();
    let mut invalid = Vec::new();
    for token in input.split(',') {
        let lower = token.to_ascii_lowercase();
        match Language::from_alias(&lower) {
            Some(lang) => { if !out.contains(&lang) { out.push(lang); } }
            None => invalid.push(token.to_string()),
        }
    }
    if invalid.is_empty() { Ok(out) } else { Err(invalid) }
}

