pub fn named_color(name: &str) -> Color {
    match name {
        "black"=>Color::Black, "red"=>Color::Red, "green"=>Color::Green, "yellow"=>Color::Yellow,
        "blue"=>Color::Blue, "magenta"=>Color::Magenta, "cyan"=>Color::Cyan, "gray"=>Color::Gray,
