        "light_yellow"=>Color::LightYellow, "light_blue"=>Color::LightBlue, "light_magenta"=>Color::LightMagenta,
        "light_cyan"=>Color::LightCyan, "white"=>Color::White, _=>Color::White,
    }
}

pub fn parse_color_value(v: &serde_json::Value) -> Color {
    if let Some(s) = v.as_str() { return named_color(s); }
    let r = v.get("r").and_then(|x| x.as_u64()).unwrap_or(255) as u8;
    let g = v.get("g").and_then(|x| x.as_u64()).unwrap_or(255) as u8;
    let b = v.get("b").and_then(|x| x.as_u64()).unwrap_or(255) as u8;
    Color::Rgb(r, g, b)
}

