    add(&mut v, "Legendary", &[("GPU Cluster",11401.,11700.),("DNS Overlord",11701.,12250.),("CDN Sentinel",12251.,12800.),("Load Balancer Primarch",12801.,13400.),("Singularity",13401.,13950.),("The Machine",13951.,14500.),("Quantum Singularity",14501.,16000.),("Neural Overlord",16001.,18000.),("Digital Deity",18001.,21000.),("Code God",21001.,25000.),("System Overlord",25001.,30000.),("Cyber Deity",30001.,36000.),("Machine God",36001.,43000.),("The Architect",43001.,48000.),("Kernel Panic",48001.,f64::MAX)]);
