                if ft.is_file() {
                    count += 1;
                    if let Ok(md) = e.metadata() { total += md.len(); }
                }
            }
        }
    }
    println!("Challenge Cache Statistics:");
    println!("  Cached repositories: {}", count);
    println!("  Total size: {}", format_size(total));
    Ok(())
}

pub fn cache_clear() -> AppResult<()> {
    let dir = cache_dir();
    if let Ok(entries) = std::fs::read_dir(&dir) {
        for e in entries.flatten() {
            if let Ok(ft) = e.file_type() {
                if ft.is_file() { let _ = std::fs::remove_file(e.path()); }
            }
        }
    }
    println!("Challenge cache cleared successfully.");
    Ok(())
}

#[derive(serde::Serialize, serde::Deserialize)]
pub struct CacheFile {
    pub key: String,
    pub challenges: Vec<crate::model::Challenge>,
}

pub fn cache_key_for(remote_sanitized: &str, commit: &str) -> String {
    format!("{}:{}", remote_sanitized, commit)
}

pub fn cache_filename(key: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(key.as_bytes());
    format!("{:x}.bin", hasher.finalize())
}

pub fn save_cache(key: &str, challenges: &[crate::model::Challenge]) -> AppResult<()> {
    let dir = cache_dir();
    std::fs::create_dir_all(&dir)?;
    let cf = CacheFile { key: key.to_string(), challenges: challenges.to_vec() };
    // clone challenge via serde json roundtrip for ownership simplicity
    let cf = CacheFile { key: cf.key, challenges: serde_json::from_value(serde_json::to_value(&cf.challenges).unwrap_or(serde_json::Value::Null)).unwrap_or_default() };
    let data = serde_json::to_vec(&cf).unwrap_or_default();
    let filename = cache_filename(key);
    let path = dir.join(filename);
    let mut encoder = flate2::write::GzEncoder::new(Vec::new(), flate2::Compression::default());
    let _ = encoder.write_all(&data);
    let compressed = encoder.finish().unwrap_or_default();
    std::fs::write(path, compressed)?;
    Ok(())
}

pub fn load_cache(key: &str) -> Option<Vec<crate::model::Challenge>> {
    let dir = cache_dir();
    let path = dir.join(cache_filename(key));
    let data = std::fs::read(path).ok()?;
    let mut decoder = flate2::read::GzDecoder::new(&data[..]);
    let mut out = Vec::new();
    decoder.read_to_end(&mut out).ok()?;
    let cf: CacheFile = serde_json::from_slice(&out).ok()?;
    Some(cf.challenges)
}

pub fn read_cache_key(path: &PathBuf) -> Option<String> {
    let data = std::fs::read(path).ok()?;
    let mut decoder = flate2::read::GzDecoder::new(&data[..]);
    let mut out = Vec::new();
    decoder.read_to_end(&mut out).ok()?;
    // Our format is JSON; original format is bincode. Only JSON will parse.
    let cf: CacheFile = serde_json::from_slice(&out).ok()?;
    Some(cf.key)
}

pub fn cache_list() -> AppResult<()> {
    let dir = cache_dir();
    let mut keys: Vec<String> = Vec::new();
    if let Ok(entries) = std::fs::read_dir(&dir) {
        let mut paths: Vec<PathBuf> = entries.flatten().map(|e| e.path()).collect();
        paths.sort();
        for p in paths {
            if p.extension().and_then(|s| s.to_str()) == Some("bin") {
                if let Some(k) = read_cache_key(&p) { keys.push(k); }
            }
        }
    }
    if keys.is_empty() {
        println!("No cached challenges found.");
    } else {
        println!("Cached repository keys:");
        for k in keys { println!("  {}", k); }
    }
    Ok(())
}
