pub fn ranks_table() -> Vec<(&'static str, &'static str, f64, f64)> {
    // (tier, name, min, max)
    let mut v: Vec<(&'static str, &'static str, f64, f64)> = Vec::new();
    let add = |v: &mut Vec<(&'static str,&'static str,f64,f64)>, tier, list: &[(&'static str,f64,f64)]| {
