pub fn rank_for_score(score: f64) -> RankInfo {
    let table = ranks_table();
    let total = table.len();
    let mut tier_counts: HashMap<&str, usize> = HashMap::new();
    for (tier, _, _, _) in &table { *tier_counts.entry(*tier).or_insert(0) += 1; }
    let mut tier_seen: HashMap<&str, usize> = HashMap::new();
    let mut chosen_idx = 0usize;
    for (i, (tier, _n, _mi, ma)) in table.iter().enumerate() {
        if score <= *ma { chosen_idx = i; break; }
        if i == table.len() - 1 { chosen_idx = i; }
        let _ = tier;
    }
    // compute tier index for chosen
    let chosen_tier = table[chosen_idx].0;
    let mut tier_index = 0usize;
    for (i, (tier, _, _, _)) in table.iter().enumerate() {
        if *tier == chosen_tier {
            if i < chosen_idx { tier_index += 1; }
        }
    }
    let _ = tier_seen;
    RankInfo {
        name: table[chosen_idx].1,
        tier: table[chosen_idx].0,
        min: table[chosen_idx].2,
        max: table[chosen_idx].3,
        tier_index,
        tier_total: *tier_counts.get(chosen_tier).unwrap_or(&0),
        global_index: chosen_idx,
        total,
    }
}

pub fn score_for_metrics(cpm: f64, accuracy: f64, mistakes: i64, streaks: &[i64]) -> f64 {
    if cpm <= 0.0 || accuracy <= 0.0 { 
        // still follow formula: base 0 -> (0 + 0 - penalty)*2+100 could be negative; original likely clamps?
        let base = cpm * (accuracy / 100.0) * 10.0;
        let penalty = mistakes as f64 * 5.0;
        return (base - penalty) * 2.0 + 100.0;
    }
    let base = cpm * (accuracy / 100.0) * 10.0;
    let consistency = if streaks.is_empty() {
        0.0
    } else {
        let avg = streaks.iter().sum::<i64>() as f64 / streaks.len() as f64;
        (avg / 75.0).clamp(0.0, 0.7)
    };
    let bonus = base * consistency;
    let penalty = mistakes as f64 * 5.0;
    (base + bonus - penalty) * 2.0 + 100.0
}
