use crate::{gittype_dir, AppResult};
use sha2::{Digest, Sha256};
use std::io::{Read, Write};
use std::path::PathBuf;

pub fn cache_dir() -> PathBuf { gittype_dir().join("cache") }

pub fn format_size(bytes: u64) -> String {
    if bytes < 1024 { format!("{} bytes", bytes) }
    else if bytes < 1024 * 1024 { format!("{:.1} KB", bytes as f64 / 1024.0) }
    else if bytes < 1024 * 1024 * 1024 { format!("{:.1} MB", bytes as f64 / (1024.0 * 1024.0)) }
    else { format!("{:.1} GB", bytes as f64 / (1024.0 * 1024.0 * 1024.0)) }
}

pub fn cache_stats() -> AppResult<()> {
    let dir = cache_dir();
    let mut count: u64 = 0;
    let mut total: u64 = 0;
    if let Ok(entries) = std::fs::read_dir(&dir) {
        for e in entries.flatten() {
            if let Ok(ft) = e.file_type() {
                if ft.is_file() {
                    count += 1;
                    if let Ok(md) = e.metadata() { total += md.len(); }
                }
            }
        }
    }
    println!("Challenge Cache Statistics:");
    println!("  Cached repositories: {}", count);
    println!("  Total size: {}", format_size(total));
    Ok(())
}

pub fn cache_clear() -> AppResult<()> {
    let dir = cache_dir();
    if let Ok(entries) = std::fs::read_dir(&dir) {
        for e in entries.flatten() {
            if let Ok(ft) = e.file_type() {
                if ft.is_file() { let _ = std::fs::remove_file(e.path()); }
            }
        }
    }
    println!("Challenge cache cleared successfully.");
    Ok(())
}

