        let mut stmt: *mut c_void = std::ptr::null_mut();
        let rc = unsafe { sqlite3_prepare_v2(self.ptr, csql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) };
        if rc != SQLITE_OK { return Err(self.db_error()); }
