use crate::model::{Challenge, Difficulty, Language};
use std::collections::HashSet;
use std::path::{Path, PathBuf};
use std::process::Command;

#[derive(Debug, Clone)]
pub struct RepoInfo {
    pub user_name: String,
    pub repository_name: String,
    pub remote_url: String,
    pub branch: Option<String>,
    pub commit_hash: Option<String>,
    pub is_dirty: bool,
    pub root: PathBuf,
    pub exists: bool,
    pub git_found: bool,
    pub error: Option<String>,
}
impl RepoInfo {
    pub fn display(&self) -> String { format!("{}/{}", self.user_name, self.repository_name) }
    pub fn short_commit(&self) -> Option<String> {
        self.commit_hash.as_ref().map(|c| c.chars().take(8).collect())
    }
}

pub fn sanitize_identifier(s: &str) -> String {
    s.chars().map(|c| if c.is_ascii_alphanumeric() { c } else { '_' }).collect()
}

fn git_output(dir: &Path, args: &[&str]) -> Option<String> {
    let out = Command::new("git").arg("-C").arg(dir).args(args).output().ok()?;
    if out.status.success() {
        Some(String::from_utf8_lossy(&out.stdout).trim().to_string())
    } else { None }
}

pub fn parse_remote_owner_repo(remote: &str) -> (String, String) {
    let mut s = remote.trim().to_string();
    if s.ends_with(".git") { s.truncate(s.len() - 4); }
    s = s.replace('\\', "/");
    // git@github.com:owner/repo form
    if let Some(pos) = s.rfind(':') {
        if s.contains('@') { s = s[pos + 1..].to_string(); }
    }
    let parts: Vec<&str> = s.split('/').filter(|p| !p.is_empty()).collect();
    if parts.len() >= 2 {
        (parts[parts.len() - 2].to_string(), parts[parts.len() - 1].to_string())
    } else if parts.len() == 1 {
        (parts[0].to_string(), "unknown".to_string())
    } else {
        ("local".to_string(), "unknown".to_string())
    }
}

pub fn local_repo_info(path_arg: &str) -> RepoInfo {
    let path = PathBuf::from(path_arg);
    if !path.exists() {
        return RepoInfo {
            user_name: "local".to_string(), repository_name: "unknown".to_string(),
            remote_url: format!("file://{}", path_arg), branch: None, commit_hash: None, is_dirty: false,
            root: path.clone(), exists: false, git_found: false,
            error: Some(format!("Failed to extract code chunks: Path does not exist: {}", path_arg)),
        };
    }
    let root_opt = git_output(&path, &["rev-parse", "--show-toplevel"]);
    if root_opt.is_none() {
        return RepoInfo {
            user_name: "local".to_string(), repository_name: "unknown".to_string(),
            remote_url: format!("file://{}", path_arg), branch: None, commit_hash: None, is_dirty: false,
            root: path.clone(), exists: true, git_found: false,
            error: Some("Failed to extract code chunks: Git repository not found".to_string()),
        };
    }
    let root = PathBuf::from(root_opt.unwrap());
    let branch = git_output(&root, &["branch", "--show-current"]).filter(|s| !s.is_empty());
    let commit = git_output(&root, &["rev-parse", "HEAD"]).filter(|s| !s.is_empty());
    let status = git_output(&root, &["status", "--porcelain"]);
    let is_dirty = status.map(|s| !s.is_empty()).unwrap_or(false);
    let remote = git_output(&root, &["remote", "get-url", "origin"]).filter(|s| !s.is_empty());
    let (user, repo, remote_url) = if let Some(r) = remote {
        let (u, rp) = parse_remote_owner_repo(&r);
        (u, rp, r)
    } else {
        ("local".to_string(), "unknown".to_string(), format!("file://{}", path_arg))
    };
    RepoInfo {
        user_name: user, repository_name: repo, remote_url, branch, commit_hash: commit, is_dirty,
        root, exists: true, git_found: true, error: None,
    }
}

pub fn parse_repo_spec(spec: &str) -> (String, String, String) {
    // returns (owner, repo, clone_url)
    let trimmed = spec.trim();
    if trimmed.starts_with("git@") {
        let (u, r) = parse_remote_owner_repo(trimmed);
        return (u.clone(), r.clone(), format!("https://github.com/{}/{}.git", u, r));
    }
    if trimmed.starts_with("http://") || trimmed.starts_with("https://") {
        let (u, r) = parse_remote_owner_repo(trimmed);
        let mut url = trimmed.to_string();
        if !url.ends_with(".git") { url.push_str(".git"); }
        return (u, r, url);
    }
    let parts: Vec<&str> = trimmed.split('/').filter(|p| !p.is_empty()).collect();
    if parts.len() >= 2 {
        let u = parts[0].to_string();
        let r = parts[parts.len() - 1].trim_end_matches(".git").to_string();
        (u.clone(), r.clone(), format!("https://github.com/{}/{}.git", u, r))
    } else {
        (trimmed.to_string(), "unknown".to_string(), format!("https://github.com/{}.git", trimmed))
    }
}

pub fn clone_or_get_repo(spec: &str) -> RepoInfo {
    let (owner, repo, clone_url) = parse_repo_spec(spec);
    let dest = crate::gittype_dir().join("repos").join("github.com").join(&owner).join(&repo);
    // if spec is local/unknown style but dest missing, will attempt clone and fail offline - matching original
    if dest.join(".git").exists() {
        let branch = git_output(&dest, &["branch", "--show-current"]).filter(|s| !s.is_empty());
        let commit = git_output(&dest, &["rev-parse", "HEAD"]).filter(|s| !s.is_empty());
        let status = git_output(&dest, &["status", "--porcelain"]);
        return RepoInfo {
            user_name: owner, repository_name: repo, remote_url: clone_url, branch, commit_hash: commit,
            is_dirty: status.map(|s| !s.is_empty()).unwrap_or(false), root: dest, exists: true, git_found: true, error: None,
        };
    }
    // clone
    crate::log_info("gittype::infrastructure::git::remote::remote_git_repository_client", &format!("Cloning repository: {}/{}", owner, repo));
    if let Some(parent) = dest.parent() { let _ = std::fs::create_dir_all(parent); }
    let out = Command::new("git").arg("clone").arg(&clone_url).arg(&dest).output();
    match out {
        Ok(o) if o.status.success() => {
            let branch = git_output(&dest, &["branch", "--show-current"]).filter(|s| !s.is_empty());
            let commit = git_output(&dest, &["rev-parse", "HEAD"]).filter(|s| !s.is_empty());
            RepoInfo {
                user_name: owner, repository_name: repo, remote_url: clone_url, branch, commit_hash: commit,
                is_dirty: false, root: dest, exists: true, git_found: true, error: None,
            }
        }
        Ok(o) => {
            let stderr = String::from_utf8_lossy(&o.stderr).trim().to_string();
            // cleanup partial clone dir (git usually removes, but ensure repo dir gone as in original)
            let _ = std::fs::remove_dir_all(&dest);
            let msg = if stderr.is_empty() { "failed to clone repository".to_string() } else { stderr.lines().last().unwrap_or("").to_string() };
            RepoInfo {
                user_name: owner, repository_name: repo, remote_url: clone_url, branch: None, commit_hash: None,
                is_dirty: false, root: dest, exists: true, git_found: false,
                error: Some(format!("Repository clone error: {}", msg)),
            }
        }
        Err(e) => RepoInfo {
            user_name: owner, repository_name: repo, remote_url: clone_url, branch: None, commit_hash: None,
            is_dirty: false, root: dest, exists: true, git_found: false,
            error: Some(format!("Repository clone error: {}", e)),
        },
    }
}

pub fn scan_all_files(root: &Path) -> usize {
    fn walk(dir: &Path, count: &mut usize) {
        if let Ok(entries) = std::fs::read_dir(dir) {
            for e in entries.flatten() {
                let p = e.path();
                if let Ok(ft) = e.file_type() {
                    if ft.is_dir() { walk(&p, count); }
                    else if ft.is_file() { *count += 1; }
                }
            }
        }
    }
    let mut c = 0; walk(root, &mut c); c
}

pub fn collect_source_files(root: &Path, langs_filter: &Option<Vec<Language>>) -> Vec<(String, PathBuf, Language)> {
    let mut out = Vec::new();
    fn walk(dir: &Path, root: &Path, out: &mut Vec<(String, PathBuf, Language)>, filter: &Option<Vec<Language>>) {
        let mut entries: Vec<PathBuf> = std::fs::read_dir(dir).map(|rd| rd.flatten().map(|e| e.path()).collect()).unwrap_or_default();
        entries.sort();
        for p in entries {
            if p.is_dir() {
                if p.file_name().and_then(|s| s.to_str()) == Some(".git") { continue; }
                walk(&p, root, out, filter);
            } else if p.is_file() {
                if let Some(ext) = p.extension().and_then(|s| s.to_str()) {
                    if let Some(lang) = Language::from_extension(ext) {
                        if let Some(f) = filter { if !f.contains(&lang) { continue; } }
                        let rel = p.strip_prefix(root).unwrap_or(&p).to_string_lossy().replace('\\', "/");
                        out.push((rel, p.clone(), lang));
                    }
                }
            }
        }
    }
    walk(root, root, &mut out, langs_filter);
    out
}

fn uuid_v4() -> String {
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let mut b = [0u8; 16];
    rng.fill(&mut b);
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    format!("{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7], b[8], b[9], b[10], b[11], b[12], b[13], b[14], b[15])
}

#[derive(Debug, Clone)]
struct Construct { start: usize, end: usize } // 0-indexed lines inclusive

fn is_brace_language(lang: Language) -> bool {
    !matches!(lang, Language::Python | Language::Ruby | Language::Haskell)
}

fn line_starts_construct(line: &str, lang: Language) -> bool {
    let t = line.trim_start();
    if t.is_empty() || t.starts_with("//") || t.starts_with('#') && lang != Language::Python { 
        // still python comments start with # but not constructs
        if t.starts_with("//") { return false; }
    }
    if t.starts_with('#') { return false; }
    match lang {
        Language::Python => {
            (t.starts_with("def ") || t.starts_with("async def ") || t.starts_with("class ") ||
             t.starts_with("if ") || t.starts_with("elif ") || t.starts_with("for ") || t.starts_with("while ") ||
             t.starts_with("try:") || t.starts_with("try ") || t.starts_with("with "))
        }
        Language::Rust => {
            let s = strip_rust_modifiers(t);
            s.starts_with("fn ") || s.starts_with("struct ") || s.starts_with("enum ") || s.starts_with("impl ") || s.starts_with("trait ") ||
            s.starts_with("if ") || s.starts_with("for ") || s.starts_with("while ") || s.starts_with("match ") || s.starts_with("loop ") || s.starts_with("mod ")
        }
        Language::Go => {
            t.starts_with("func ") || t.starts_with("type ") || t.starts_with("if ") || t.starts_with("for ") || t.starts_with("switch ") || t.starts_with("select ")
        }
        Language::TypeScript | Language::JavaScript => {
            t.starts_with("function ") || t.starts_with("async function ") || t.starts_with("export function ") || t.starts_with("export async function ") ||
            t.starts_with("class ") || t.starts_with("export class ") || t.starts_with("interface ") || t.starts_with("export interface ") || t.starts_with("enum ") ||
            t.starts_with("if ") || t.starts_with("for ") || t.starts_with("while ") || t.starts_with("switch ") ||
            // method: name(...) {
            is_method_like(t)
        }
        Language::Ruby => {
            t.starts_with("def ") || t.starts_with("class ") || t.starts_with("module ") || t.starts_with("if ") || t.starts_with("for ") || t.starts_with("while ") || t.starts_with("begin")
        }
        Language::Haskell => {
            // function definitions at top-level without indentation handled elsewhere
            false
        }
        _ => {
            // generic brace languages: Java, C#, PHP, Swift, Kotlin, C, C++, Dart, Scala, Zig
            let keywords = ["class ", "struct ", "interface ", "enum ", "trait ", "protocol ", "extension ", "object ", "namespace ", "impl ",
                            "if ", "for ", "while ", "switch ", "func ", "fun ", "fn ", "function ", "def ", "public ", "private ", "protected ", "static ", "async ", "void ", "int ", "string ", "bool ", "double ", "float ", "var ", "let ", "const "];
            if keywords.iter().any(|k| t.starts_with(k)) { return true; }
            is_method_like(t)
        }
    }
}

fn strip_rust_modifiers(t: &str) -> &str {
    let mut s = t;
    for m in ["pub(crate) ", "pub(super) ", "pub ", "async ", "unsafe ", "const ", "extern \"C\" ", "default "] {
        if let Some(rest) = s.strip_prefix(m) { s = rest; }
    }
    // loop for combined modifiers
    for _ in 0..3 {
        let mut changed = false;
        for m in ["pub ", "async ", "unsafe ", "const "] {
            if let Some(rest) = s.strip_prefix(m) { s = rest; changed = true; }
        }
        if !changed { break; }
    }
    s
}

fn is_method_like(t: &str) -> bool {
    // name(...) { or name(...) -> ... { etc, and line contains '(' and ')'
    if !t.contains('(') { return false; }
    // avoid statements like "if(" handled, calls ending with ;
    if t.ends_with(';') { return false; }
    // must look like identifier followed by (
    let before_paren = t.split('(').next().unwrap_or("");
    let last_word = before_paren.split_whitespace().last().unwrap_or("");
    if last_word.is_empty() { return false; }
    last_word.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '.')
        && last_word.chars().next().map(|c| c.is_ascii_alphabetic() || c == '_').unwrap_or(false)
        && !matches!(last_word, "if" | "for" | "while" | "switch" | "return" | "print" | "println")
}

fn brace_delta(line: &str) -> i32 {
    let mut delta = 0i32;
    let mut in_str: Option<char> = None;
    let mut prev = '\0';
    for c in line.chars() {
        if let Some(q) = in_str {
            if prev != '\\' && c == q { in_str = None; }
        } else if c == '"' || c == '\'' || c == '`' {
            // apostrophe in python code like I'm: only treat as string if prev is not alphanum? simplify: treat double quote only
            if c == '"' || c == '`' { in_str = Some(c); }
        } else if c == '{' { delta += 1; } else if c == '}' { delta -= 1; }
        prev = c;
    }
    delta
}

fn extract_constructs(lines: &[String], lang: Language) -> Vec<Construct> {
    let mut result = Vec::new();
    let mut seen = HashSet::new();
    if lang == Language::Haskell {
        // top-level function definitions: lines at col0 with "name ... ="
        let mut i = 0;
        while i < lines.len() {
            let line = &lines[i];
            if !line.is_empty() && !line.starts_with(|c: char| c.is_whitespace()) && line.contains('=') && !line.starts_with("--") {
                let start = i;
                let mut end = i;
                let mut j = i + 1;
                while j < lines.len() {
                    let l = &lines[j];
                    if l.trim().is_empty() { j += 1; continue; }
                    if l.starts_with(|c: char| c.is_whitespace()) { end = j; j += 1; } else { break; }
                }
                if seen.insert((start, end)) { result.push(Construct { start, end }); }
                i = j;
            } else { i += 1; }
        }
        return result;
    }
    for i in 0..lines.len() {
        if !line_starts_construct(&lines[i], lang) { continue; }
        let start = i;
        let end = if is_brace_language(lang) {
            // if line ends with ; -> single line
            if lines[i].trim_end().ends_with(';') && !lines[i].contains('{') { i }
            else {
                let mut depth = 0i32;
                let mut opened = false;
                let mut end = i;
                for j in i..lines.len() {
                    let d = brace_delta(&lines[j]);
                    if lines[j].contains('{') { opened = true; }
                    depth += d;
                    end = j;
                    if opened && depth <= 0 { break; }
                    // safety: if no brace within 3 lines and it's trait sig etc
                    if !opened && j >= i + 2 { end = i; break; }
                    if j == lines.len() - 1 { end = j; }
                }
                if !opened { i } else { end }
            }
        } else if lang == Language::Ruby {
            // find matching 'end' at same indent
            let indent = lines[i].len() - lines[i].trim_start().len();
            let mut end = i;
            for j in i + 1..lines.len() {
                let l = &lines[j];
                let ind = l.len() - l.trim_start().len();
                end = j;
                if ind == indent && l.trim() == "end" { break; }
                if j == lines.len() - 1 { end = j; }
            }
            end
        } else {
            // python indentation
            let indent = lines[i].len() - lines[i].trim_start().len();
            let mut end = i;
            for j in i + 1..lines.len() {
                let l = &lines[j];
                if l.trim().is_empty() { continue; }
                let ind = l.len() - l.trim_start().len();
                if ind > indent { end = j; } else { break; }
            }
            end
        };
        if seen.insert((start, end)) { result.push(Construct { start, end }); }
    }
    result
}

fn lines_text(lines: &[String], start: usize, end: usize) -> String {
    let mut s = String::new();
    for i in start..=end {
        if i < lines.len() { s.push_str(&lines[i]); s.push('\n'); }
    }
    s
}

fn effective_len(text: &str) -> usize {
    text.lines().map(|l| l.trim().len()).sum::<usize>() + text.lines().count().saturating_sub(1)
}

fn raw_len(text: &str) -> usize { text.chars().count() }

fn truncate_range(lines: &[String], start: usize, end: usize, target: usize) -> usize {
    // return end index of first line where cumulative raw length >= target, starting at start
    let mut cum = 0usize;
    for i in start..=end {
        cum += lines[i].chars().count() + 1;
        if cum >= target { return i; }
    }
    end
}

fn make_challenge(file_path: &str, start_line: usize, end_line: usize, language: Language, code: String, difficulty: Difficulty) -> Challenge {
    Challenge {
        id: uuid_v4(),
        file_path: file_path.to_string(),
        start_line, end_line,
        language: language.canonical().to_string(),
        code_content: code,
        difficulty: difficulty.name().to_string(),
        comment_ranges: vec![],
    }
}

pub fn extract_challenges(root: &Path, langs_filter: &Option<Vec<Language>>) -> (Vec<Challenge>, usize, usize) {
    let total_files = scan_all_files(root);
    let source_files = collect_source_files(root, langs_filter);
    let extraction_files = source_files.len();
    let mut challenges = Vec::new();
    for (rel_path, abs_path, lang) in &source_files {
        let content = match std::fs::read_to_string(abs_path) { Ok(c) => c, Err(_) => continue };
        let lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
        if lines.is_empty() { continue; }
        // File chunk entries
        let file_text = lines_text(&lines, 0, lines.len() - 1);
        let file_raw = raw_len(&file_text);
        // Zen
        challenges.push(make_challenge(rel_path, 1, lines.len(), *lang, file_text.clone(), Difficulty::Zen));
        // Wild file
        challenges.push(make_challenge(rel_path, 1, lines.len(), *lang, file_text.clone(), Difficulty::Wild));
        // File difficulty variants
        if file_raw >= 40 {
            // Easy snippet
            let mut easy_end = truncate_range(&lines, 0, lines.len() - 1, 100);
            // extend to blank line if within next 3 lines (observed file snippets ending at blank)
            if easy_end < lines.len() - 1 {
                for k in easy_end + 1..=(easy_end + 3).min(lines.len() - 1) {
                    if lines[k].trim().is_empty() { easy_end = k; break; }
                }
            }
            let easy_text = lines_text(&lines, 0, easy_end);
            challenges.push(make_challenge(rel_path, 1, easy_end + 1, *lang, easy_text, Difficulty::Easy));
        }
        if file_raw >= 110 {
            challenges.push(make_challenge(rel_path, 1, lines.len(), *lang, file_text.clone(), Difficulty::Normal));
        }
        if file_raw >= 270 {
            challenges.push(make_challenge(rel_path, 1, lines.len(), *lang, file_text.clone(), Difficulty::Hard));
        }
        // AST constructs
        let constructs = extract_constructs(&lines, *lang);
        for c in constructs {
            let text = lines_text(&lines, c.start, c.end);
            let rlen = raw_len(&text);
            let elen = effective_len(&text);
            // Wild for every construct
            challenges.push(make_challenge(rel_path, c.start + 1, c.end + 1, *lang, text.clone(), Difficulty::Wild));
            if rlen >= 35 {
                // Easy (full if not too long else truncated)
                if rlen > 200 {
                    let e_end = truncate_range(&lines, c.start, c.end, 100);
                    let e_text = lines_text(&lines, c.start, e_end);
                    challenges.push(make_challenge(rel_path, c.start + 1, e_end + 1, *lang, e_text, Difficulty::Easy));
                } else {
                    challenges.push(make_challenge(rel_path, c.start + 1, c.end + 1, *lang, text.clone(), Difficulty::Easy));
                }
                if elen >= 100 && rlen < 280 {
                    // Normal full (or truncated if very long)
                    challenges.push(make_challenge(rel_path, c.start + 1, c.end + 1, *lang, text.clone(), Difficulty::Normal));
                }
                if rlen >= 280 {
                    challenges.push(make_challenge(rel_path, c.start + 1, c.end + 1, *lang, text.clone(), Difficulty::Hard));
                }
            }
        }
    }
    (challenges, total_files, extraction_files)
}
