#[derive(Debug, Clone)]
pub struct StageOutcome {
    pub challenge: Challenge,
    pub keystrokes: i64,
    pub mistakes: i64,
    pub duration_ms: i64,
    pub cpm: f64,
    pub wpm: f64,
    pub accuracy: f64,
    pub score: f64,
    pub streaks: Vec<i64>,
    pub was_skipped: bool,
    pub was_failed: bool,
}

#[derive(Debug, Clone, Default)]
pub struct SessionAggregate {
    pub keystrokes: i64,
    pub mistakes: i64,
    pub duration_ms: i64,
    pub cpm: f64,
    pub wpm: f64,
    pub accuracy: f64,
    pub score: f64,
    pub stages_completed: i64,
    pub stages_attempted: i64,
    pub stages_skipped: i64,
}

pub fn aggregate_outcomes(outcomes: &[StageOutcome]) -> SessionAggregate {
    let completed: Vec<&StageOutcome> = outcomes.iter().filter(|o| !o.was_skipped && !o.was_failed).collect();
    let keystrokes: i64 = outcomes.iter().map(|o| o.keystrokes).sum();
    let mistakes: i64 = outcomes.iter().map(|o| o.mistakes).sum();
    let duration_ms: i64 = completed.iter().map(|o| o.duration_ms).sum();
    let correct = keystrokes - mistakes;
    let minutes = duration_ms as f64 / 60000.0;
    let cpm = if minutes > 0.0 { (completed.iter().map(|o| o.keystrokes - o.mistakes).sum::<i64>() as f64) / minutes } else { 0.0 };
    let accuracy = if keystrokes > 0 { correct as f64 / keystrokes as f64 * 100.0 } else { 0.0 };
    let mut all_streaks: Vec<i64> = Vec::new();
    for o in &completed { all_streaks.extend(o.streaks.iter().cloned()); }
    let score = crate::model::score_for_metrics(cpm, accuracy, mistakes, &all_streaks);
    SessionAggregate {
        keystrokes, mistakes, duration_ms, cpm, wpm: cpm / 5.0, accuracy, score,
        stages_completed: completed.len() as i64,
        stages_attempted: outcomes.len() as i64,
        stages_skipped: outcomes.iter().filter(|o| o.was_skipped).count() as i64,
    }
}
