// ---------- repo clear ----------
fn count_git_repos(dir: &std::path::Path) -> usize {
    let mut count = 0usize;
    fn walk(dir: &std::path::Path, count: &mut usize) {
        if dir.join(".git").exists() { *count += 1; return; }
        if let Ok(entries) = std::fs::read_dir(dir) {
            for e in entries.flatten() {
                let p = e.path();
                if p.is_dir() { walk(&p, count); }
            }
        }
    }
    walk(dir, &mut count);
    count
}

pub fn repo_clear(force: bool) -> AppResult<()> {
    let repos_dir = gittype_dir().join("repos");
    if !repos_dir.exists() {
        println!("No cached repositories directory found.");
        return Ok(());
    }
    let count = count_git_repos(&repos_dir);
    if count == 0 {
        println!("No cached repositories found.");
        return Ok(());
    }
    if !force {
        println!("This will delete all locally cached repositories in:");
        println!("  {}", repos_dir.display());
        println!("({} cached repositories will be removed)", count);
        print!("Are you sure you want to continue? [y/N]: ");
        let _ = io::stdout().flush();
        let mut line = String::new();
        let _ = io::stdin().read_line(&mut line);
        let ans = line.trim().to_ascii_lowercase();
        if ans != "y" && ans != "yes" {
            println!("Operation cancelled.");
            return Ok(());
        }
    }
    let _ = std::fs::remove_dir_all(&repos_dir);
    println!("Successfully deleted all cached repositories.");
    println!("Cache directory {} has been removed.", repos_dir.display());
    Ok(())
}

