impl ThemeManager {
    pub fn load(create_custom: bool) -> Self {
        let themes = load_themes();
        let (lang_dark, lang_light, lang_ascii) = load_language_colors();
        // config
        let mut theme_id = "default".to_string();
        let mut mode = "Dark".to_string();
        let config_path = gittype_dir().join("config.json");
        if let Ok(text) = std::fs::read_to_string(&config_path) {
            if let Ok(cfg) = serde_json::from_str::<ThemeConfigFile>(&text) {
                theme_id = cfg.theme.current_theme_id;
                mode = cfg.theme.current_color_mode;
            }
        }
        // custom theme file
        let custom_path = gittype_dir().join("custom-theme.json");
        if create_custom && !custom_path.exists() {
            if let Some(def) = themes.get(0) {
                let obj = serde_json::json!({ "dark": def.dark_json, "light": def.light_json });
                if let Ok(text) = serde_json::to_string_pretty(&obj) {
                    let _ = std::fs::create_dir_all(gittype_dir());
                    let _ = std::fs::write(&custom_path, text);
                }
            }
        }
        let mut custom_dark = None;
        let mut custom_light = None;
        if let Ok(text) = std::fs::read_to_string(&custom_path) {
            if let Ok(v) = serde_json::from_str::<serde_json::Value>(&text) {
                if let Some(d) = v.get("dark") { custom_dark = Some(Palette::from_json(d)); }
                if let Some(l) = v.get("light") { custom_light = Some(Palette::from_json(l)); }
            }
        }
        Self { themes, lang_dark, lang_light, lang_ascii, current_theme_id: theme_id, current_color_mode: mode, custom_dark, custom_light }
    }

    pub fn theme_index(&self) -> usize {
        if self.current_theme_id == "custom" { return self.themes.len(); }
        self.themes.iter().position(|t| t.id == self.current_theme_id).unwrap_or(0)
    }
    pub fn theme_name_at(&self, idx: usize) -> String {
        if idx >= self.themes.len() { "Custom".to_string() } else { self.themes[idx].name.clone() }
    }
    pub fn theme_desc_at(&self, idx: usize) -> String {
        if idx >= self.themes.len() { "Your personal custom theme - edit ~/.gittype/custom-theme.json to customize".to_string() } else { self.themes[idx].description.clone() }
    }
    pub fn palette_for(&self, theme_idx: usize, mode: &str) -> Palette {
        if theme_idx >= self.themes.len() {
            // custom
            if mode == "Light" {
                if let Some(p) = &self.custom_light { return p.clone(); }
            } else if let Some(p) = &self.custom_dark { return p.clone(); }
            // fallback default
            let def = &self.themes[0];
            return if mode == "Light" { def.light.clone() } else { def.dark.clone() };
        }
        let t = &self.themes[theme_idx];
        if mode == "Light" { t.light.clone() } else { t.dark.clone() }
    }
    pub fn palette(&self) -> Palette {
        self.palette_for(self.theme_index(), &self.current_color_mode.clone())
    }
    pub fn lang_color(&self, canonical: &str) -> Color {
        let key = format!("lang_{}", canonical);
        let is_ascii = self.current_theme_id == "ascii";
        let map = if is_ascii { &self.lang_ascii } else if self.current_color_mode == "Light" { &self.lang_light } else { &self.lang_dark };
        map.get(&key).cloned().or_else(|| map.get("lang_default").cloned()).unwrap_or(Color::White)
    }
    pub fn save_config(&self, theme_idx: usize, mode: &str) -> AppResult<()> {
        let id = if theme_idx >= self.themes.len() { "custom".to_string() } else { self.themes[theme_idx].id.clone() };
