pub fn digit_glyphs(text: &str) -> Vec<String> {
    // 4-row digit font
    let glyph = |c: char| -> [&'static str; 4] {
        match c {
            '0' => [" ___ ", "/ _ \\", "| () |", " \\__/ "],
            '1' => [" _ ", "/ |", "| |", "|_|"],
            '2' => [" ___ ", "|_  )", " / / ", "/___|"],
            '3' => [" ___ ", "|__ /", " |_ \\", "|___/"],
            '4' => [" _ _ ", "| | |", "|_  _|", "  |_|"],
            '5' => [" ___ ", "| __|", "|__ \\", "|___/"],
            '6' => [" __ ", "/ / ", "/ _ \\", "\\___/"],
            '7' => [" ____ ", "|__  |", "   / /", "  /_/ "],
            '8' => [" ___ ", "( _ )", "/ _ \\", "\\___/"],
            '9' => [" ___ ", "/ _ \\", "\\_, /", " /_/ "],
            _ => [" ", " ", " ", " "],
        }
    };
    let mut rows = vec![String::new(); 4];
    for (idx, c) in text.chars().enumerate() {
        let g = glyph(c);
        let w = g.iter().map(|s| s.chars().count()).max().unwrap_or(0);
        for r in 0..4 {
            if idx > 0 { rows[r].push_str("  "); }
            let s = g[r];
            rows[r].push_str(s);
            for _ in s.chars().count()..w { rows[r].push(' '); }
        }
    }
    rows
}

