// ---------- terminal ----------
pub fn setup_terminal() -> AppResult<Terminal<CrosstermBackend<io::Stdout>>> {
    enable_raw_mode().map_err(|e| AppError::new(format!("Terminal error: Failed to create terminal: {}", e)))?;
    let mut stdout = io::stdout();
    if let Err(e) = execute!(stdout, EnterAlternateScreen) {
        let _ = disable_raw_mode();
        return Err(AppError::new(format!("Terminal error: Failed to create terminal: {}", e)));
    }
    let backend = CrosstermBackend::new(stdout);
    let term = Terminal::new(backend).map_err(|e| AppError::new(format!("Terminal error: Failed to create terminal: {}", e)))?;
    Ok(term)
}
pub fn restore_terminal(term: &mut Terminal<CrosstermBackend<io::Stdout>>) {
    let _ = disable_raw_mode();
    let _ = execute!(term.backend_mut(), LeaveAlternateScreen);
    let _ = term.show_cursor();
}

