#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TypingPhase { Waiting, Countdown, Active }

pub struct TypingState {
    pub challenge: Challenge,
    pub phase: TypingPhase,
    pub countdown_start: Option<Instant>,
    pub active_start: Option<Instant>,
    pub target: Vec<char>,
    pub pos: usize,
    pub keystrokes: i64,
    pub mistakes: i64,
    pub streaks: Vec<i64>,
    pub current_streak: i64,
    pub options_open: bool,
    pub last_mistake_pos: Option<usize>,
    pub display_lines: Vec<String>,
    pub challenge_start_display_line: usize, // 1-indexed in display lines
    pub challenge_end_display_line: usize,
    pub finished_outcome: Option<StageOutcome>,
}
impl TypingState {
    pub fn new(challenge: Challenge, repo_root: Option<&std::path::Path>) -> Self {
        // display lines: full file if readable, else code_content
        let mut display_lines: Vec<String> = Vec::new();
        let mut start_line = challenge.start_line;
        let mut end_line = challenge.end_line;
        if let Some(root) = repo_root {
            let path = root.join(&challenge.file_path);
            if let Ok(content) = std::fs::read_to_string(&path) {
                display_lines = content.lines().map(|s| s.to_string()).collect();
            }
        }
        if display_lines.is_empty() {
            display_lines = challenge.code_content.lines().map(|s| s.to_string()).collect();
            // display starts at 1 but original line numbers still use challenge.start_line for header; for line numbers rendering we offset
            // Keep start_line as challenge lines: we render line numbers as challenge.start_line + idx, so store mapping via start_line field
            start_line = challenge.start_line;
            end_line = challenge.end_line;
        } else {
            start_line = challenge.start_line;
            end_line = challenge.end_line;
        }
        let target_str = challenge.code_content.trim_end_matches('\n').trim_end_matches('\r').to_string();
        let mut target: Vec<char> = target_str.chars().collect();
        // If target ends with trailing spaces on last line, trim?
        while matches!(target.last(), Some('\r')) { target.pop(); }
        let mut state = Self {
            challenge: challenge.clone(), phase: TypingPhase::Waiting, countdown_start: None, active_start: None,
            target, pos: 0, keystrokes: 0, mistakes: 0, streaks: Vec::new(), current_streak: 0,
            options_open: false, last_mistake_pos: None, display_lines,
            challenge_start_display_line: start_line, challenge_end_display_line: end_line, finished_outcome: None,
        };
        state.skip_indent();
        state
    }
    pub fn skip_indent(&mut self) {
        // skip leading indentation at start, and after newline positions
        loop {
            if self.pos >= self.target.len() { break; }
            let c = self.target[self.pos];
            if (c == ' ' || c == '\t') && (self.pos == 0 || self.target[self.pos - 1] == '\n') {
                self.pos += 1;
            } else { break; }
        }
    }
    pub fn elapsed_secs(&self) -> f64 {
        if let Some(s) = self.active_start { s.elapsed().as_secs_f64() } else { 0.0 }
    }
    pub fn correct(&self) -> i64 { self.keystrokes - self.mistakes }
    pub fn metrics(&self) -> (f64, f64, f64) {
        let minutes = self.elapsed_secs() / 60.0;
        let cpm = if minutes > 0.0 { self.correct() as f64 / minutes } else { 0.0 };
        let acc = if self.keystrokes > 0 { self.correct() as f64 / self.keystrokes as f64 * 100.0 } else { 0.0 };
        (cpm, cpm / 5.0, acc)
    }
    pub fn make_outcome(&self, skipped: bool, failed: bool) -> StageOutcome {
        let duration_ms = if let Some(s) = self.active_start { s.elapsed().as_millis() as i64 } else { 0 };
        let minutes = duration_ms as f64 / 60000.0;
        let cpm = if minutes > 0.0 { self.correct() as f64 / minutes } else { 0.0 };
        let acc = if self.keystrokes > 0 { self.correct() as f64 / self.keystrokes as f64 * 100.0 } else { 0.0 };
        let mut streaks = self.streaks.clone();
        if self.current_streak > 0 { streaks.push(self.current_streak); }
        let score = if skipped || failed { self_partial_score(cpm, acc, self.mistakes, &streaks) } else { crate::model::score_for_metrics(cpm, acc, self.mistakes, &streaks) };
        StageOutcome { challenge: self.challenge.clone(), keystrokes: self.keystrokes, mistakes: self.mistakes, duration_ms, cpm, wpm: cpm / 5.0, accuracy: acc, score, streaks, was_skipped: skipped, was_failed: failed }
    }
}
fn self_partial_score(cpm: f64, acc: f64, mistakes: i64, streaks: &[i64]) -> f64 { crate::model::score_for_metrics(cpm, acc, mistakes, streaks) }

