        // settings preview handling is done by temporarily updating theme fields in settings logic; palette() uses theme current values
        self.theme.palette()
    }
    pub fn preview_palette(&self) -> Palette {
        if self.screen == Screen::Settings {
            let mode = if self.settings_color_idx == 1 { "Light" } else { "Dark" };
            self.theme.palette_for(self.settings_theme_idx, mode)
        } else { self.theme.palette() }
    }
