pub fn load_records_from_db(db: &Db) -> AppResult<Vec<RecordItem>> {
    let rows = db.query("SELECT sr.id, sr.session_id, sr.repository_id, s.started_at, r.user_name, r.repository_name, sr.score, sr.cpm, sr.wpm, sr.accuracy, sr.stages_completed, sr.stages_attempted, sr.duration_ms, s.branch, s.commit_hash FROM session_results sr JOIN sessions s ON s.id = sr.session_id JOIN repositories r ON r.id = sr.repository_id", &[])?;
