            stages_completed: r.int(10).unwrap_or(0), stages_attempted: r.int(11).unwrap_or(0), duration_ms: r.int(12).unwrap_or(0),
            branch: r.text(13), commit_hash: r.text(14),
        });
    }
    Ok(out)
}

pub fn load_repo_items_from_db(db: &Db) -> AppResult<Vec<RepoPlayedItem>> {
    let rows = db.query("SELECT id, user_name, repository_name, remote_url FROM repositories ORDER BY id", &[])?;
    let mut out = Vec::new();
    for r in rows {
        let repo_id = r.int(0).unwrap_or(0);
        let mut langs: Vec<String> = Vec::new();
        if let Ok(lang_rows) = db.query("SELECT language FROM stage_results WHERE repository_id = ? GROUP BY language ORDER BY MIN(id)", &[Value::Int(repo_id)]) {
            for lr in lang_rows {
                if let Some(l) = lr.text(0) {
                    let disp = Language::from_canonical(&l).map(|x| x.display().to_string()).unwrap_or_else(|| {
                        let mut chars = l.chars(); match chars.next() { Some(c) => c.to_ascii_uppercase().to_string() + chars.as_str(), None => l.clone() }
                    });
                    langs.push(disp);
                }
            }
        }
        let avg_cpm = db.query("SELECT AVG(cpm) FROM session_results WHERE repository_id = ?", &[Value::Int(repo_id)])
            .ok().and_then(|rows| rows.get(0).and_then(|row| row.real(0))).unwrap_or(0.0);
        out.push(RepoPlayedItem {
            user_name: r.text(1).unwrap_or_default(), repository_name: r.text(2).unwrap_or_default(), remote_url: r.text(3).unwrap_or_default(),
            languages: langs, cached: false, repository_id: repo_id, avg_cpm,
        });
    }
    // cached detection via cache keys
    let mut cached_idents: HashSet<String> = HashSet::new();
    if let Ok(entries) = std::fs::read_dir(cache::cache_dir()) {
        for e in entries.flatten() {
            let p = e.path();
            if p.extension().and_then(|s| s.to_str()) == Some("bin") {
                if let Some(k) = cache::read_cache_key(&p) {
                    if let Some((ident, _)) = k.rsplit_once(':') { cached_idents.insert(ident.to_string()); }
                }
            }
        }
    }
    for item in out.iter_mut() {
        item.cached = cached_idents.contains(&extract::sanitize_identifier(&item.remote_url));
    }
    Ok(out)
}

pub fn insert_session_to_db(app: &mut App) {
    if app.session.as_ref().map(|s| s.saved).unwrap_or(true) { return; }
    let Some(db) = app.db.as_ref() else { return; };
    let Some(repo) = app.repo_info.as_ref() else { return; };
    let outcomes = app.session.as_ref().unwrap().outcomes.clone();
    if outcomes.is_empty() { return; }
    let agg = aggregate_outcomes(&outcomes);
    // repository
    let repo_id: i64 = {
        let rows = db.query("SELECT id FROM repositories WHERE user_name = ? AND repository_name = ?", &[Value::Text(repo.user_name.clone()), Value::Text(repo.repository_name.clone())]).unwrap_or_default();
        if let Some(r) = rows.get(0) { r.int(0).unwrap_or(0) } else {
            db.execute("INSERT INTO repositories (user_name, repository_name, remote_url) VALUES (?, ?, ?)", &[Value::Text(repo.user_name.clone()), Value::Text(repo.repository_name.clone()), Value::Text(repo.remote_url.clone())]).unwrap_or(0)
        }
    };
    if repo_id == 0 { return; }
    let now_str = chrono::Local::now().format("%Y-%m-%d %H:%M:%S").to_string();
    // challenges + stages + stage results
    // completed stages for best/worst
    let completed: Vec<&StageOutcome> = outcomes.iter().filter(|o| !o.was_skipped && !o.was_failed).collect();
    let best_stage = completed.iter().max_by(|a, b| a.wpm.partial_cmp(&b.wpm).unwrap_or(std::cmp::Ordering::Equal));
    let worst_stage = completed.iter().min_by(|a, b| a.wpm.partial_cmp(&b.wpm).unwrap_or(std::cmp::Ordering::Equal));
    let best_wpm = best_stage.map(|s| s.wpm).unwrap_or(0.0);
    let worst_wpm = worst_stage.map(|s| s.wpm).unwrap_or(0.0);
    let best_acc = best_stage.map(|s| s.accuracy).unwrap_or(0.0);
    let worst_acc = worst_stage.map(|s| s.accuracy).unwrap_or(0.0);
    let rank = rank_for_score(agg.score);
    let difficulty_name = app.difficulty.name();
    let session_id = db.execute("INSERT INTO sessions (repository_id, started_at, completed_at, branch, commit_hash, is_dirty, game_mode, difficulty_level, max_stages, time_limit_seconds) VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL)",
        &[Value::Int(repo_id), Value::Text(now_str.clone()), Value::Text(now_str.clone()),
          repo.branch.as_ref().map(|s| Value::Text(s.clone())).unwrap_or(Value::Null),
          repo.commit_hash.as_ref().map(|s| Value::Text(s.clone())).unwrap_or(Value::Null),
          Value::Int(if repo.is_dirty {1} else {0}), Value::Text(difficulty_name.to_string()), Value::Text(difficulty_name.to_string())]).unwrap_or(0);
    if session_id == 0 { return; }
    for (idx, o) in outcomes.iter().enumerate() {
        let ch = &o.challenge;
        let _ = db.execute("INSERT OR IGNORE INTO challenges (id, file_path, start_line, end_line, language, code_content, comment_ranges, difficulty_level) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            &[Value::Text(ch.id.clone()), Value::Text(ch.file_path.clone()), Value::Int(ch.start_line as i64), Value::Int(ch.end_line as i64), Value::Text(ch.language.clone()), Value::Text(ch.code_content.clone()), Value::Text("[]".to_string()), Value::Text(ch.difficulty.clone())]);
        let stage_id = db.execute("INSERT INTO stages (session_id, challenge_id, stage_number, started_at, completed_at) VALUES (?, ?, ?, ?, ?)",
            &[Value::Int(session_id), Value::Text(ch.id.clone()), Value::Int((idx + 1) as i64), Value::Text(now_str.clone()), Value::Text(now_str.clone())]).unwrap_or(0);
        if stage_id == 0 { continue; }
        let srank = rank_for_score(o.score);
        let streaks_json = serde_json::to_string(&o.streaks).unwrap_or_else(|_| "[]".to_string());
        let _ = db.execute("INSERT INTO stage_results (stage_id, session_id, repository_id, keystrokes, mistakes, duration_ms, wpm, cpm, accuracy, consistency_streaks, score, rank_name, tier_name, rank_position, rank_total, position, total, was_skipped, was_failed, completed_at, language, difficulty_level) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            &[Value::Int(stage_id), Value::Int(session_id), Value::Int(repo_id), Value::Int(o.keystrokes), Value::Int(o.mistakes), Value::Int(o.duration_ms), Value::Real(o.wpm), Value::Real(o.cpm), Value::Real(o.accuracy), Value::Text(streaks_json), Value::Real(o.score), Value::Text(srank.name.to_string()), Value::Text(srank.tier.to_string()), Value::Int(srank.rank_position() as i64), Value::Int(srank.tier_total as i64), Value::Int(srank.position() as i64), Value::Int(srank.total as i64), Value::Int(if o.was_skipped {1} else {0}), Value::Int(if o.was_failed {1} else {0}), Value::Text(now_str.clone()), Value::Text(ch.language.clone()), Value::Text(ch.difficulty.clone())]);
    }
    let _ = db.execute("INSERT INTO session_results (session_id, repository_id, keystrokes, mistakes, duration_ms, wpm, cpm, accuracy, stages_completed, stages_attempted, stages_skipped, partial_effort_keystrokes, partial_effort_mistakes, best_stage_wpm, worst_stage_wpm, best_stage_accuracy, worst_stage_accuracy, score, rank_name, tier_name, rank_position, rank_total, position, total, game_mode, difficulty_level) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        &[Value::Int(session_id), Value::Int(repo_id), Value::Int(agg.keystrokes), Value::Int(agg.mistakes), Value::Int(agg.duration_ms), Value::Real(agg.wpm), Value::Real(agg.cpm), Value::Real(agg.accuracy), Value::Int(agg.stages_completed), Value::Int(agg.stages_attempted), Value::Int(agg.stages_skipped), Value::Real(best_wpm), Value::Real(worst_wpm), Value::Real(best_acc), Value::Real(worst_acc), Value::Real(agg.score), Value::Text(rank.name.to_string()), Value::Text(rank.tier.to_string()), Value::Int(rank.rank_position() as i64), Value::Int(rank.tier_total as i64), Value::Int(rank.position() as i64), Value::Int(rank.total as i64), Value::Text(difficulty_name.to_string()), Value::Text(difficulty_name.to_string())]);
    if let Some(sess) = app.session.as_mut() {
        sess.saved = true;
        sess.saved_session_id = session_id;
        sess.aggregate_at_save = Some(agg);
    }
}
