// ---------- public entry points ----------
pub fn run_game(repo_path: Option<String>, repo_spec: Option<String>, langs: Option<String>) -> AppResult<()> {
    log_info("gittype::presentation::cli::commands::game", "Starting GitType game session");
    // langs validation (prints and exits directly, no fatal error file - as in original)
    let mut langs_filter: Option<Vec<Language>> = None;
    if let Some(ref l) = langs {
        match validate_langs(l) {
            Ok(v) => langs_filter = Some(v),
            Err(invalid) => {
                eprintln!("❌ Unsupported language(s): {}", invalid.join(", "));
                eprintln!("💡 Supported languages:");
                eprintln!("   rust, rs, typescript, ts, javascript, js");
                eprintln!("   python, py, ruby, rb, go, swift");
                eprintln!("   kotlin, kt, java, php, csharp, cs");
                eprintln!("   c#, c, cpp, c++, haskell, hs");
                eprintln!("   dart, scala, sc, zig, clojure, clj");
                eprintln!("   cljs");
                std::process::exit(1);
