// ---------- main loop ----------
pub fn run_loop(term: &mut Terminal<CrosstermBackend<io::Stdout>>, app: &mut App) -> AppResult<()> {
    loop {
        term.draw(|f| draw_screen(f, app)).map_err(|e| AppError::new(format!("Terminal error: Failed to create terminal: {}", e)))?;
        // timers
        update_timers(app);
        if app.should_quit { break; }
        if event::poll(Duration::from_millis(50)).unwrap_or(false) {
            if let Ok(Event::Key(key)) = event::read() {
                if key.kind == event::KeyEventKind::Release { continue; }
                if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('c') {
                    app.should_quit = true; break;
                }
                handle_key(app, key.code, key.modifiers);
                if app.should_quit { break; }
            }
        }
        if app.screen == Screen::Loading {
            loading_tick(app);
        }
        if app.should_quit { break; }
    }
    Ok(())
}

fn update_timers(app: &mut App) {
    // typing countdown
    if app.screen == Screen::Typing {
        let mut complete_countdown = false;
        if let Some(ts) = &app.typing {
            if ts.phase == TypingPhase::Countdown {
                if let Some(start) = ts.countdown_start {
                    if start.elapsed() >= Duration::from_millis(3000) { complete_countdown = true; }
                }
            }
        }
        if complete_countdown {
            if let Some(ts) = &mut app.typing {
                ts.phase = TypingPhase::Active;
                ts.active_start = Some(Instant::now());
                ts.skip_indent();
            }
        }
    }
    if app.screen == Screen::Animation {
        if let Some(start) = app.animation_start {
            let msgs = animation_messages(&app.animation_language);
            let total_ms: u64 = msgs.iter().map(|m| (m.chars().count() as u64) * 22 + 250).sum();
            if start.elapsed() >= Duration::from_millis(total_ms) {
                finish_animation(app);
            }
        }
    }
}

