fn loading_tick(app: &mut App) {
    let now = Instant::now();
    let last = app.loading_last_advance.unwrap_or(now);
    if now.duration_since(last) < Duration::from_millis(140) { return; }
    app.loading_last_advance = Some(now);
    let step = app.loading_step;
    match step {
        0 => {
            // database init
            log_info("gittype::presentation::game::models::loading_steps::database_init_step", "DatabaseInitStep: Starting database initialization");
            match Db::open(&db_path()).and_then(|db| { db.init_schema()?; Ok(db) }) {
                Ok(db) => {
                    app.db = Some(db);
                    log_info("gittype::presentation::game::models::loading_steps::database_init_step", "DatabaseInitStep: Database initialized successfully");
                    log_info("gittype::presentation::game::models::loading_steps::database_init_step", "DatabaseInitStep: Global session repository initialized successfully");
                }
                Err(e) => {
                    // proceed without db
                    log_error("gittype::presentation::tui::screens::loading_screen", &format!("Database initialization failed: {}", e.message));
                }
            }
            app.loading_step = 1;
        }
        1 => {
            // clone / repo determination
            if let Some(spec) = app.repo_spec.clone() {
                let info = extract::clone_or_get_repo(&spec);
                if let Some(err) = &info.error {
                    app.loading_error = Some(err.clone());
                    log_error("gittype::presentation::tui::screens::loading_screen", &format!("Repository processing failed: {}", err));
                    app.repo_info = Some(info);
                    app.set_screen(Screen::Title);
                    return;
                }
                app.repo_info = Some(info);
            } else {
                let path_arg = app.repo_path_arg.clone().unwrap_or_else(|| ".".to_string());
                let info = extract::local_repo_info(&path_arg);
                app.repo_info = Some(info);
            }
            app.loading_step = 2;
        }
        2 => {
            // cache check
            if let Some(info) = &app.repo_info {
                if let Some(err) = &info.error {
                    log_info("gittype::presentation::game::models::loading_steps::cache_check_step", "No git repository info - skipping cache check");
                    log_error("gittype::presentation::tui::screens::loading_screen", &format!("Repository processing failed: {}", err));
                    app.loading_error = Some(err.clone());
                    app.set_screen(Screen::Title);
                    return;
                }
            }
            log_info("gittype::presentation::game::models::loading_steps::cache_check_step", "No git repository info - skipping cache check");
            app.loading_step = 3;
        }
        3 => {
            if let Some(info) = &app.repo_info {
                if info.git_found { app.scanned_files = extract::scan_all_files(&info.root); }
            }
            app.loading_step = 4;
        }
        4 => {
            if let Some(info) = app.repo_info.clone() {
                if info.git_found {
                    let (challenges, _total, extraction_files) = extract::extract_challenges(&info.root, &app.langs_filter);
                    app.challenges = challenges;
                    app.extraction_files = extraction_files;
                }
            }
            app.loading_step = 5;
        }
        5 => {
            // generating / caching
            if let Some(info) = app.repo_info.clone() {
                if info.git_found {
                    if let Some(commit) = &info.commit_hash {
                        let key = cache::cache_key_for(&extract::sanitize_identifier(&info.remote_url), commit);
                        let _ = cache::save_cache(&key, &app.challenges);
                        log_info("gittype::presentation::game::models::loading_steps::generating_step", &format!("Successfully cached {} challenges for {}", app.challenges.len(), info.remote_url));
                    }
                }
            }
            log_info("gittype::presentation::game::stage_repository", "✅ StageRepository: Title screen data ready (will be updated by ScreenManager)");
            app.set_screen(Screen::Title);
        }
        _ => {
            app.set_screen(Screen::Title);
        }
    }
