// ---------- drawing helpers ----------
fn s_rgb(c: Color) -> Style { Style::default().fg(c) }

fn centered_block_area(area: Rect, content_height: u16) -> Rect {
    let y = if area.height > content_height { area.y + (area.height - content_height) / 2 } else { area.y };
    Rect::new(area.x, y, area.width, content_height.min(area.height))
}

fn draw_centered_lines(f: &mut Frame, area: Rect, lines: Vec<Line>) {
    let h = lines.len() as u16;
    let rect = centered_block_area(area, h.max(1));
    let p = Paragraph::new(lines).alignment(Alignment::Center);
    f.render_widget(p, rect);
}

fn bordered_block<'a>(title: &'a str, pal: &Palette) -> Block<'a> {
    Block::default().borders(Borders::ALL).border_style(s_rgb(pal.border)).title(Span::styled(title.to_string(), s_rgb(pal.border)))
}
fn bordered_block_plain<'a>(pal: &Palette) -> Block<'a> {
    Block::default().borders(Borders::ALL).border_style(s_rgb(pal.border))
}

fn key_span(pal: &Palette, kind: &str, text: &str) -> Span<'static> {
    let color = match kind { "back" => pal.key_back, "action" => pal.key_action, _ => pal.key_navigation };
    Span::styled(text.to_string(), s_rgb(color))
}

fn draw_screen(f: &mut Frame, app: &App) {
    match app.screen {
        Screen::Loading => draw_loading(f, app),
        Screen::Title => draw_title(f, app),
        Screen::Typing => draw_typing(f, app),
        Screen::StageSummary => draw_stage_summary(f, app),
        Screen::Animation => draw_animation(f, app),
        Screen::SessionSummary => draw_session_summary(f, app),
        Screen::DetailsDialog => draw_details_dialog(f, app),
        Screen::SessionSharing => draw_sharing(f, app),
        Screen::TotalSummary => draw_total_summary(f, app),
        Screen::SessionFailure => draw_session_failure(f, app),
        Screen::Records => draw_records(f, app),
        Screen::SessionDetail => draw_session_detail(f, app),
        Screen::Analytics => draw_analytics(f, app),
        Screen::Settings => draw_settings(f, app),
        Screen::Help => draw_help(f, app),
        Screen::RepoList => draw_repo_list(f, app),
        Screen::RepoPlay => draw_repo_play(f, app),
        Screen::TrendingLanguageSelection => draw_trending_languages(f, app),
        Screen::TrendingRepositorySelection => draw_trending_repos(f, app),
    }
}

// ---------- Loading ----------
fn draw_loading(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    let step_names = [
        "Initializing database and session recording",
        "Cloning repository from remote source",
        "Checking cache for existing challenges",
        "Scanning repository files",
        "Extracting functions, classes, and code blocks",
        "Generating challenges across difficulty levels",
    ];
    let mut lines: Vec<Line> = Vec::new();
    lines.push(Line::from(Span::styled("» Loading...", s_rgb(pal.title))));
    lines.push(Line::from(""));
    lines.push(Line::from(Span::styled("Analyzing your repository to create typing challenges...", s_rgb(pal.text))));
    lines.push(Line::from(""));
    for (i, name) in step_names.iter().enumerate() {
        let (icon, style) = if (i as usize) < app.loading_step { ("✓", s_rgb(pal.status_success)) } else if i == app.loading_step { ("⚡", s_rgb(pal.status_warning)) } else { ("○", s_rgb(pal.text_secondary)) };
        lines.push(Line::from(vec![Span::styled(format!("{} ", icon), style), Span::styled(name.to_string(), s_rgb(pal.text))]));
    }
    lines.push(Line::from(""));
    // progress area rendered separately below text (full width) - include placeholder lines
    let has_gauge = app.loading_step >= 1;
    if has_gauge { lines.push(Line::from("")); lines.push(Line::from("")); }
    let content_h = lines.len() as u16;
    let rect = centered_block_area(area, content_h);
    let p = Paragraph::new(lines.clone()).alignment(Alignment::Center);
    f.render_widget(p, rect);
    if has_gauge {
        let gauge_y = rect.y + content_h - 2;
        if gauge_y < area.y + area.height {
            let gauge_area = Rect::new(area.x, gauge_y, area.width, 1);
            let gauge = Gauge::default().percent(100).label("100%").gauge_style(s_rgb(pal.status_info));
            f.render_widget(gauge, gauge_area);
            let spinner_chars = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
            let spin = spinner_chars[((app.loading_started.map(|s| s.elapsed().as_millis()).unwrap_or(0) / 100) % spinner_chars.len() as u128) as usize];
            let detail = match app.loading_step {
                1 => format!("{} 100.0%", spin),
                2 => format!("{} 100.0% 1/1 files", spin),
                3 => if app.scanned_files > 0 { format!("{} 100.0% {}/{} files", spin, app.scanned_files, app.scanned_files) } else { format!("{} 0.0% 0/1 files", spin) },
                4 => format!("{} 100.0% {}/{} files", spin, app.extraction_files, app.extraction_files),
                _ => format!("{} 100.0%", spin),
            };
            let detail_area = Rect::new(area.x, gauge_y + 1, area.width, 1);
            f.render_widget(Paragraph::new(Line::from(Span::styled(detail, s_rgb(pal.text)))).alignment(Alignment::Center), detail_area);
        }
    }
}

// ---------- Title ----------
fn draw_title(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    // footer area
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Min(0), Constraint::Length(1)]).split(area);
    let main = chunks[0];
    let footer = chunks[1];
    let gradient: [(u8, u8, u8); 18] = [(129,135,215),(117,135,215),(105,135,215),(95,136,215),(95,147,215),(95,159,215),(95,171,215),(75,175,215),(47,175,215),(19,175,215),(0,171,215),(0,159,215),(0,147,215),(0,136,215),(0,135,225),(0,135,237),(0,135,249),(0,135,255)];
    let banner_raw = [
        "  ____ _ _  _____",
        " / ___(_) ||_   _|   _ _ __   ___",
        "| |  _| | __|| || | | | '_ \\ / _ \\",
        "| |_| | | |_ | || |_| | |_) |  __/",
        " \\____|_|\\__||_| \\__, | .__/ \\___|",
        "                 |___/|_|",
    ];
    let banner_width = banner_raw.iter().map(|s| s.chars().count()).max().unwrap_or(0);
    let mut content_height: u16 = 17;
    if app.title_error.is_some() { content_height = 16; }
    let top = if main.height > content_height { main.y + (main.height - content_height) / 2 } else { main.y };
    // render banner manually with gradient per 2 chars
    for (row, line_str) in banner_raw.iter().enumerate() {
        let y = top + row as u16;
        if y >= main.y + main.height { break; }
        let x_start = main.x + (main.width.saturating_sub(banner_width as u16)) / 2;
        let mut spans: Vec<Span> = Vec::new();
        let chars: Vec<char> = line_str.chars().collect();
        let mut i = 0;
        while i < chars.len() {
            let gi = (i / 2).min(gradient.len() - 1);
            let (r, g, b) = gradient[gi];
            let chunk: String = chars.iter().skip(i).take(2).collect();
            spans.push(Span::styled(chunk, Style::default().fg(Color::Rgb(r, g, b))));
            i += 2;
        }
        f.render_widget(Paragraph::new(Line::from(spans)), Rect::new(x_start, y, banner_width as u16, 1));
    }
    // remaining lines
    let mut lines: Vec<Line> = Vec::new();
