// ---------- drawing helpers ----------
fn s_rgb(c: Color) -> Style { Style::default().fg(c) }

fn centered_block_area(area: Rect, content_height: u16) -> Rect {
    let y = if area.height > content_height { area.y + (area.height - content_height) / 2 } else { area.y };
    Rect::new(area.x, y, area.width, content_height.min(area.height))
}

fn draw_centered_lines(f: &mut Frame, area: Rect, lines: Vec<Line>) {
    let h = lines.len() as u16;
    let rect = centered_block_area(area, h.max(1));
    let p = Paragraph::new(lines).alignment(Alignment::Center);
    f.render_widget(p, rect);
}

fn bordered_block<'a>(title: &'a str, pal: &Palette) -> Block<'a> {
