fn draw_title(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    // footer area
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Min(0), Constraint::Length(1)]).split(area);
    let main = chunks[0];
    let footer = chunks[1];
    let gradient: [(u8, u8, u8); 18] = [(129,135,215),(117,135,215),(105,135,215),(95,136,215),(95,147,215),(95,159,215),(95,171,215),(75,175,215),(47,175,215),(19,175,215),(0,171,215),(0,159,215),(0,147,215),(0,136,215),(0,135,225),(0,135,237),(0,135,249),(0,135,255)];
    let banner_raw = [
        "  ____ _ _  _____",
        " / ___(_) ||_   _|   _ _ __   ___",
        "| |  _| | __|| || | | | '_ \\ / _ \\",
        "| |_| | | |_ | || |_| | |_) |  __/",
        " \\____|_|\\__||_| \\__, | .__/ \\___|",
        "                 |___/|_|",
    ];
    let banner_width = banner_raw.iter().map(|s| s.chars().count()).max().unwrap_or(0);
    let mut content_height: u16 = 17;
    if app.title_error.is_some() { content_height = 16; }
    let top = if main.height > content_height { main.y + (main.height - content_height) / 2 } else { main.y };
    // render banner manually with gradient per 2 chars
    for (row, line_str) in banner_raw.iter().enumerate() {
        let y = top + row as u16;
        if y >= main.y + main.height { break; }
        let x_start = main.x + (main.width.saturating_sub(banner_width as u16)) / 2;
        let mut spans: Vec<Span> = Vec::new();
        let chars: Vec<char> = line_str.chars().collect();
        let mut i = 0;
        while i < chars.len() {
            let gi = (i / 2).min(gradient.len() - 1);
            let (r, g, b) = gradient[gi];
            let chunk: String = chars.iter().skip(i).take(2).collect();
            spans.push(Span::styled(chunk, Style::default().fg(Color::Rgb(r, g, b))));
            i += 2;
        }
        f.render_widget(Paragraph::new(Line::from(spans)), Rect::new(x_start, y, banner_width as u16, 1));
    }
    // remaining lines
    let mut lines: Vec<Line> = Vec::new();
    lines.push(Line::from(""));
    lines.push(Line::from(Span::styled("Code Typing Challenge", s_rgb(pal.text_secondary))));
    lines.push(Line::from(""));
    lines.push(Line::from(vec![
        Span::styled("Difficulty: ", s_rgb(pal.text)),
        Span::styled("← ", s_rgb(pal.metrics_accuracy)),
        Span::styled(app.difficulty.name().to_string(), Style::default().fg(pal.text).add_modifier(Modifier::BOLD)),
        Span::styled(" →", s_rgb(pal.metrics_accuracy)),
    ]));
    if let Some(err) = &app.title_error {
        if app.challenges.is_empty() {
            lines.push(Line::from(Span::styled("Challenge count will be displayed after loading", Style::default().fg(pal.status_info).add_modifier(Modifier::DIM))));
        } else {
            let cnt = app.count_for(app.difficulty);
            lines.push(Line::from(Span::styled(format!("{} challenges available", cnt), Style::default().fg(pal.status_info).add_modifier(Modifier::DIM))));
        }
        lines.push(Line::from(Span::styled(err.clone(), s_rgb(pal.status_error))));
    } else {
        if app.challenges.is_empty() {
            lines.push(Line::from(Span::styled("Challenge count will be displayed after loading", Style::default().fg(pal.status_info).add_modifier(Modifier::DIM))));
        } else {
            let cnt = app.count_for(app.difficulty);
            lines.push(Line::from(Span::styled(format!("{} challenges available", cnt), Style::default().fg(pal.status_info).add_modifier(Modifier::DIM))));
        }
        lines.push(Line::from(Span::styled(app.difficulty.char_desc().to_string(), Style::default().fg(pal.text).add_modifier(Modifier::DIM))));
        lines.push(Line::from(Span::styled(app.difficulty.desc().to_string(), Style::default().fg(pal.text).add_modifier(Modifier::DIM))));
    }
    lines.push(Line::from(""));
    lines.push(Line::from(vec![key_span(&pal, "nav", "[←→/HL]"), Span::styled(" Change Difficulty", s_rgb(pal.text))]));
    lines.push(Line::from(vec![
        key_span(&pal, "nav", "[R]"), Span::styled(" Records  ", s_rgb(pal.text)),
        key_span(&pal, "nav", "[A]"), Span::styled(" Analytics  ", s_rgb(pal.text)),
        key_span(&pal, "nav", "[S]"), Span::styled(" Settings  ", s_rgb(pal.text)),
        key_span(&pal, "nav", "[I/?]"), Span::styled(" Help", s_rgb(pal.text)),
    ]));
    lines.push(Line::from(vec![
        key_span(&pal, "action", "[SPACE]"), Span::styled(" Start  ", s_rgb(pal.text)),
        key_span(&pal, "back", "[ESC]"), Span::styled(" Quit", s_rgb(pal.text)),
    ]));
    let lines_area_y = top + 6;
    if lines_area_y < main.y + main.height {
        let h = (lines.len() as u16).min(main.y + main.height - lines_area_y);
        f.render_widget(Paragraph::new(lines).alignment(Alignment::Center), Rect::new(main.x, lines_area_y, main.width, h));
    }
    // footer repo info
    if let Some(info) = &app.repo_info {
        if info.git_found {
            let mut parts: Vec<String> = Vec::new();
            parts.push(format!("📁 {}", info.display()));
            if let Some(b) = &info.branch { parts.push(format!("🌿 {}", b)); }
            if let Some(c) = info.short_commit() { parts.push(format!("📝 {}", c)); }
            parts.push(if info.is_dirty { "⚠️".to_string() } else { "✓".to_string() });
            let text = parts.join(" • ");
            f.render_widget(Paragraph::new(Line::from(Span::styled(text, s_rgb(pal.text_secondary)))).alignment(Alignment::Center), footer);
        }
    }
}

// ---------- Typing ----------
fn draw_typing(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    let Some(ts) = &app.typing else { return; };
    let area = Rect::new(area.x.saturating_add(1), area.y, area.width.saturating_sub(2), area.height);
    let chunks = Layout::default().direction(Direction::Vertical).constraints([
        Constraint::Length(1), Constraint::Length(3), Constraint::Min(0), Constraint::Length(3), Constraint::Length(3), Constraint::Length(1),
    ]).split(area);
    let header_area = chunks[1];
    let code_area = chunks[2];
    let metrics_area = chunks[3];
    let progress_area = chunks[4];
    let footer_area = chunks[5];
    // header
    let lang_disp = Language::from_canonical(&ts.challenge.language).map(|l| l.display().to_string()).unwrap_or_else(|| ts.challenge.language.clone());
    let header_block = bordered_block("Challenge", &pal);
    let repo_disp = app.repo_info.as_ref().map(|i| i.display()).unwrap_or_else(|| "local/unknown".to_string());
    let header_line = Line::from(vec![
        Span::styled(format!(" [{}] {}:{}-{} ", repo_disp, ts.challenge.file_path, ts.challenge.start_line, ts.challenge.end_line), s_rgb(pal.text_secondary)),
        Span::styled(format!("[{}]", lang_disp), s_rgb(app.theme.lang_color(&ts.challenge.language))),
        Span::styled(format!(" [{}]", ts.challenge.difficulty), s_rgb(pal.text_secondary)),
    ]);
    f.render_widget(Paragraph::new(header_line).block(header_block), header_area);
    // code
    let mut code_block = Block::default().borders(Borders::ALL).border_style(s_rgb(pal.border)).title(Span::styled("Code", s_rgb(pal.status_success)));
    let code_inner = code_block.inner(code_area);
    f.render_widget(code_block.clone(), code_area);
    match ts.phase {
        TypingPhase::Waiting => {
            let inner_lines: Vec<Line> = vec![Line::from("")];
            let _ = inner_lines;
            let h = code_inner.height;
            let y = code_inner.y + h / 2;
            f.render_widget(Paragraph::new(Line::from(Span::styled("Press [SPACE] to start", s_rgb(pal.text)))).alignment(Alignment::Center), Rect::new(code_inner.x, y, code_inner.width, 1));
        }
        TypingPhase::Countdown => {
            if let Some(start) = ts.countdown_start {
                let elapsed = start.elapsed().as_secs_f64();
                let num = if elapsed < 1.0 { "3" } else if elapsed < 2.0 { "2" } else { "1" };
                let glyphs = digit_glyphs(num);
                let y = code_inner.y + code_inner.height.saturating_sub(4) / 2;
                for (i, row) in glyphs.iter().enumerate() {
                    f.render_widget(Paragraph::new(Line::from(Span::styled(row.clone(), s_rgb(pal.title)))).alignment(Alignment::Center), Rect::new(code_inner.x, y + i as u16, code_inner.width, 1));
                }
            }
        }
        TypingPhase::Active => {
            draw_typing_code(f, app, code_inner, ts);
        }
    }
    // metrics
    let (cpm, wpm, acc) = ts.metrics();
    let skips = app.session.as_ref().map(|s| s.skips_remaining).unwrap_or(3);
    let metrics_block = bordered_block("Metrics", &pal);
    let metrics_line = Line::from(Span::styled(format!(" WPM: {} | CPM: {} | Accuracy: {}% | Mistakes: {} | Streak: {} | Time: {}s | Skips: {}", wpm.round() as i64, cpm.round() as i64, acc.floor() as i64, ts.mistakes, ts.current_streak, ts.elapsed_secs().floor() as i64, skips), s_rgb(pal.text)));
    f.render_widget(Paragraph::new(metrics_line).block(metrics_block), metrics_area);
    // progress
    let progress_block = bordered_block("Progress", &pal);
    let progress_inner = progress_block.inner(progress_area);
    f.render_widget(progress_block, progress_area);
    let percent = if ts.target.is_empty() { 0 } else { ((ts.pos as f64 / ts.target.len() as f64) * 100.0).floor() as u16 };
    let gauge = Gauge::default().percent(percent.min(100)).label(format!("{}%", percent.min(100))).gauge_style(s_rgb(pal.status_info));
    f.render_widget(gauge, progress_inner);
    // footer
    f.render_widget(Paragraph::new(Line::from(vec![key_span(&pal, "back", "[ESC]"), Span::styled(" Options", s_rgb(pal.text))])), footer_area);
    // options popup
    if ts.options_open {
        draw_options_popup(f, app);
    }
}

fn draw_options_popup(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    let skips = app.session.as_ref().map(|s| s.skips_remaining).unwrap_or(3);
    let width = 48u16.min(area.width);
    let height = 9u16.min(area.height);
    let x = area.x + (area.width.saturating_sub(width)) / 2;
    let y = area.y + (area.height.saturating_sub(height)) / 2;
    let rect = Rect::new(x, y, width, height);
    f.render_widget(Clear, rect);
    let block = Block::default().borders(Borders::ALL).border_style(s_rgb(pal.border)).title("Game Options");
    let lines = vec![
        Line::from(""),
        Line::from(Span::styled("Choose an option:", s_rgb(pal.text))).alignment(Alignment::Center),
        Line::from(""),
        Line::from(Span::styled(format!("[S] Skip challenge ({})", skips), s_rgb(pal.text))).alignment(Alignment::Center),
        Line::from(Span::styled("[Q] Quit (fail)", s_rgb(pal.text))).alignment(Alignment::Center),
        Line::from(Span::styled("[ESC] Back to game", s_rgb(pal.text))).alignment(Alignment::Center),
        Line::from(""),
    ];
    f.render_widget(Paragraph::new(lines).block(block), rect);
}

fn draw_typing_code(f: &mut Frame, app: &App, inner: Rect, ts: &TypingState) {
    let pal = app.palette();
    if inner.height == 0 { return; }
    // blank first row
    // determine excerpt
    let total_lines = ts.display_lines.len();
    if total_lines == 0 { return; }
    // display line numbers are original if display is full file: start at 1 else challenge.start_line
    let is_full_file = ts.challenge_start_display_line <= total_lines && {
        // if we read full file, display_lines length likely > challenge range; distinguish by checking challenge start line number vs lines
        // We stored start as challenge.start_line both cases; for full file, line idx 0 corresponds to line 1
        // For fallback (code only), line idx 0 corresponds to challenge.start_line
        // Heuristic: if challenge.code_content lines count != display_lines count, full file
        ts.challenge.code_content.lines().count() != total_lines
    };
    let display_line_number = |idx: usize| -> usize {
        if is_full_file { idx + 1 } else { ts.challenge_start_display_line + idx }
    };
    // Build position mapping: char index in target for each file line char
    // Create mapping arrays for displayed excerpt lines
    // Target text lines:
    let target_text: String = ts.target.iter().collect();
    let target_lines: Vec<String> = target_text.lines().map(|s| s.to_string()).collect();
    // Determine excerpt range in display indices
    let challenge_start_idx_in_display: usize = if is_full_file { ts.challenge.start_line.saturating_sub(1) } else { 0 };
    let challenge_end_idx_in_display: usize = if is_full_file { ts.challenge.end_line.saturating_sub(1).min(total_lines - 1) } else { total_lines - 1 };
    let excerpt_start = challenge_start_idx_in_display.saturating_sub(4).max(0);
    let excerpt_end = (challenge_end_idx_in_display + 4).min(total_lines - 1);
    // current line determination from pos: count newlines in target before pos
    let current_target_line: usize = ts.target.iter().take(ts.pos.min(ts.target.len())).filter(|&&c| c == '\n').count();
    let cursor_display_idx = challenge_start_idx_in_display + current_target_line;
    let visible_rows = inner.height.saturating_sub(1) as usize; // first row blank
    let mut scroll_top = cursor_display_idx.saturating_sub(excerpt_start).saturating_sub(12);
    // scroll_top is offset within excerpt
    let excerpt_len = excerpt_end + 1 - excerpt_start;
    if excerpt_len > visible_rows {
        let max_scroll = excerpt_len - visible_rows;
        if scroll_top > max_scroll { scroll_top = max_scroll; }
    }
    // For whole-file challenge, original scrolls even when fits: keep computed scroll_top as above
    // Build target char positions per challenge line
    // offset mapping: for each challenge line l (0-based in target), char positions
    let mut line_char_positions: Vec<Vec<usize>> = Vec::new();
    let mut pos_counter = 0usize;
    for (li, line) in target_lines.iter().enumerate() {
        let mut v = Vec::new();
        for _ch in line.chars() { v.push(pos_counter); pos_counter += 1; }
        line_char_positions.push(v);
        // newline after line (except maybe after last line if target doesn't end with newline - target trimmed, lines() loses final newline)
        if li + 1 < target_lines.len() || target_text.ends_with('\n') { pos_counter += 1; } // newline index is previous pos_counter-? handled in symbol logic
        // Actually newline position is the index counted before increment, we recompute later
    }
    // recompute newline positions:
    let mut newline_positions: Vec<usize> = Vec::new();
    {
        let mut idx = 0usize;
        for c in ts.target.iter() { if *c == '\n' { newline_positions.push(idx); } idx += 1; }
    }
    let mut y = inner.y + 1;
    // cumulative target offset per target line for newline idx lookup
    let mut target_line_start_offsets: Vec<usize> = Vec::new();
    {
        let mut off = 0usize;
        for line in &target_lines {
            target_line_start_offsets.push(off);
            off += line.chars().count() + 1; // + newline
        }
    }
    for excerpt_offset in scroll_top..excerpt_len {
        if y >= inner.y + inner.height { break; }
        let display_idx = excerpt_start + excerpt_offset;
        let line_text = &ts.display_lines[display_idx];
        let line_no = display_line_number(display_idx);
        let is_current_line = display_idx == cursor_display_idx;
        let ln_style = if is_current_line { Style::default().fg(pal.status_warning).add_modifier(Modifier::BOLD) } else { s_rgb(pal.text_secondary) };
        let mut spans: Vec<Span> = Vec::new();
        spans.push(Span::styled(format!(" {:>4} │ ", line_no), ln_style));
        let in_challenge = display_idx >= challenge_start_idx_in_display && display_idx <= challenge_end_idx_in_display;
        if !in_challenge {
            spans.push(Span::styled(line_text.clone(), s_rgb(pal.text_secondary)));
        } else {
            let target_line_idx = display_idx - challenge_start_idx_in_display;
            if target_line_idx < target_lines.len() {
                let target_line = &target_lines[target_line_idx];
                // For each character in display line, map to target char: display line should match target line (for full file it does; fallback too)
                let line_start_offset = target_line_start_offsets.get(target_line_idx).cloned().unwrap_or(0);
                for (ci, _ch) in display_line_chars(line_text).iter().enumerate() {
                    let char_pos = line_start_offset + ci;
                    // If ci is beyond target line chars (e.g. display has trailing chars not in target), treat as untyped
                    let style = if ci >= target_line.chars().count() { s_rgb(pal.typing_untyped_text) }
                        else if char_pos < ts.pos { s_rgb(pal.typing_typed_text) }
                        else if char_pos == ts.pos { 
                            if ts.last_mistake_pos == Some(char_pos) { Style::default().fg(pal.typing_cursor_fg).bg(pal.typing_mistake_bg) } else { Style::default().fg(pal.typing_cursor_fg).bg(pal.typing_cursor_bg) }
                        } else { s_rgb(pal.typing_untyped_text) };
                    let ch_str = display_line_chars(line_text)[ci].to_string();
                    spans.push(Span::styled(ch_str, style));
                }
                // newline symbol if line is not empty (original shows ↵ even on last line)
                if !line_text.is_empty() {
                    let newline_pos = line_start_offset + target_line.chars().count();
                    // newline exists in target if target_line_idx < target_lines len... target trimmed so last line may not have newline in target but original displays ↵ - style as untyped/cursor accordingly
                    let style = if newline_pos < ts.pos { s_rgb(pal.typing_typed_text) }
                        else if newline_pos == ts.pos { if ts.last_mistake_pos == Some(newline_pos) { Style::default().fg(pal.typing_cursor_fg).bg(pal.typing_mistake_bg) } else { Style::default().fg(pal.typing_cursor_fg).bg(pal.typing_cursor_bg) } }
                        else { s_rgb(pal.typing_untyped_text) };
                    // Only show ↵ if the corresponding newline is part of target OR it is not the very last line of file? Original shows on last challenge line too.
                    spans.push(Span::styled("↵", style));
                }
            } else {
                spans.push(Span::styled(line_text.clone(), s_rgb(pal.typing_untyped_text)));
            }
        }
        f.render_widget(Paragraph::new(Line::from(spans)), Rect::new(inner.x, y, inner.width, 1));
        y += 1;
    }
    let _ = line_char_positions;
    let _ = newline_positions;
}

fn display_line_chars(s: &str) -> Vec<char> { s.chars().collect() }
