fn share_text(app: &App) -> String {
    let agg = session_aggregate_for_summary(app);
    let rank = rank_for_score(agg.score);
    let repo_disp = app.repo_info.as_ref().map(|i| i.display()).unwrap_or_else(|| "local/unknown".to_string());
    format!("\"{}\" with {}pts on [{}] - CPM: {}, Mistakes: {}", rank.name, agg.score as i64, repo_disp, agg.cpm as i64, agg.mistakes)
}
fn share_url(app: &App, platform: usize) -> String {
    let agg = session_aggregate_for_summary(app);
    let rank = rank_for_score(agg.score);
    let repo_disp = app.repo_info.as_ref().map(|i| i.display()).unwrap_or_else(|| "local/unknown".to_string());
    let text = format!("Achieved \"{}\" with {}pts on [{}] in gittype! CPM: {}, Mistakes: {} 🚀\n\nType your own code! https://github.com/unhappychoice/gittype\n\n#gittype #typing #coding", rank.name, agg.score as i64, repo_disp, agg.cpm as i64, agg.mistakes);
    let enc = url_encode(&text);
    match platform {
        1 => format!("https://www.reddit.com/submit?title={}&url={}", enc, url_encode("https://github.com/unhappychoice/gittype")),
        2 => format!("https://www.linkedin.com/sharing/share-offsite/?url={}", url_encode("https://github.com/unhappychoice/gittype")),
        3 => format!("https://www.facebook.com/sharer/sharer.php?u={}&quote={}", url_encode("https://github.com/unhappychoice/gittype"), enc),
        _ => format!("https://x.com/intent/tweet?text={}", enc),
    }
}
fn url_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        let c = b as char;
        if c.is_ascii_alphanumeric() || matches!(c, '-' | '_' | '.' | '~' | '!') { out.push(c); }
        else { out.push_str(&format!("%{:02X}", b)); }
    }
    out
}
fn platform_name(idx: usize) -> &'static str { match idx { 0=>"X", 1=>"Reddit", 2=>"LinkedIn", 3=>"Facebook", _=>"X" } }

