fn draw_animation(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    let msgs = animation_messages(&app.animation_language);
    let start = app.animation_start.unwrap_or_else(Instant::now);
    let elapsed_ms = start.elapsed().as_millis() as u64;
    let mut lines: Vec<Line> = Vec::new();
    let mut remaining = elapsed_ms;
    let block_width = msgs.iter().map(|m| m.chars().count() + 2).max().unwrap_or(0);
    for msg in &msgs {
        let msg_ms = (msg.chars().count() as u64) * 22 + 250;
        if remaining >= msg_ms {
            lines.push(Line::from(Span::styled(format!("> {}", msg), s_rgb(pal.text))));
            remaining -= msg_ms;
        } else {
            let typed_chars = (remaining / 22).min(msg.chars().count() as u64) as usize;
            let partial: String = msg.chars().take(typed_chars).collect();
            lines.push(Line::from(vec![Span::styled(format!("> {}", partial), s_rgb(pal.text)), Span::styled("█", s_rgb(pal.text))]));
            break;
        }
    }
    // left-aligned block centred horizontally
    let y_start = if area.height > 8 { area.y + area.height / 3 } else { area.y };
    let x_start = if (area.width as usize) > block_width { area.x + ((area.width as usize - block_width) / 2) as u16 } else { area.x };
    for (i, line) in lines.into_iter().enumerate() {
        let y = y_start + i as u16;
        if y < area.y + area.height { f.render_widget(Paragraph::new(line), Rect::new(x_start, y, (block_width as u16).min(area.width), 1)); }
    }
    // footer [S] Skip at bottom right
    let footer_y = area.y + area.height.saturating_sub(1);
    f.render_widget(Paragraph::new(Line::from(Span::styled("[S] Skip", s_rgb(pal.text)))).alignment(Alignment::Right), Rect::new(area.x, footer_y, area.width.saturating_sub(1), 1));
}

fn session_aggregate_for_summary(app: &App) -> SessionAggregate {
    if let Some(sess) = &app.session {
        if let Some(agg) = &sess.aggregate_at_save { return agg.clone(); }
        return aggregate_outcomes(&sess.outcomes);
    }
    SessionAggregate::default()
}

