fn best_record(db: Option<&Db>, period_days: Option<i64>) -> Option<RecordItem> {
    let db = db?;
    let all = load_records_from_db(db).ok()?;
    let now = chrono::Local::now().naive_local();
    let filtered: Vec<RecordItem> = all.into_iter().filter(|r| {
        if let Some(days) = period_days {
            if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(&r.started_at, "%Y-%m-%d %H:%M:%S") {
                return dt >= now - chrono::Duration::days(days);
            }
            false
        } else { true }
    }).collect();
    filtered.into_iter().max_by(|a, b| a.score.partial_cmp(&b.score).unwrap_or(std::cmp::Ordering::Equal))
}

fn draw_details_dialog(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    let agg = session_aggregate_for_summary(app);
    let db = app.db.as_ref();
    let today_best = best_record(db, Some(0));
    // period_days Some(0) interpreted above as 0 days - fix: today is date equal; our filter with 0 days will require dt >= now (time) => wrong. handle manually in display below
    let _ = today_best;
    // Compute bests manually
    let all_records = db.and_then(|d| load_records_from_db(d).ok()).unwrap_or_default();
    let today_str = chrono::Local::now().format("%Y-%m-%d").to_string();
    let pick_best = |filter: &dyn Fn(&RecordItem) -> bool| -> Option<RecordItem> {
        all_records.iter().filter(|r| filter(r)).max_by(|a, b| a.score.partial_cmp(&b.score).unwrap_or(std::cmp::Ordering::Equal)).cloned()
    };
    let today = pick_best(&|r: &RecordItem| r.started_at.starts_with(&today_str));
    let weekly = pick_best(&|r: &RecordItem| {
        if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(&r.started_at, "%Y-%m-%d %H:%M:%S") {
            dt >= chrono::Local::now().naive_local() - chrono::Duration::days(7)
        } else { false }
    });
    let alltime = pick_best(&|_: &RecordItem| true);
    let is_new_pb = alltime.as_ref().map(|r| (r.score - agg.score).abs() < 0.01 && agg.score > 0.0).unwrap_or(false) && agg.stages_completed > 0 && {
        // pb if no other record higher than current (excluding duplicate current count) - approximate as score >= all records
        all_records.iter().all(|r| r.score <= agg.score + 0.01)
    };
    let mut lines: Vec<Line> = Vec::new();
    lines.push(Line::from(Span::styled("=== SESSION DETAILS ===", s_rgb(pal.title))));
    lines.push(Line::from(""));
    lines.push(Line::from(Span::styled("BEST RECORDS", s_rgb(pal.text))));
    lines.push(Line::from(""));
    let fmt_best = |label: &str, rec: &Option<RecordItem>| -> String {
        if let Some(r) = rec { format!("{}: Score {} | CPM {} | Acc {:.1}%", label, r.score as i64, r.cpm as i64, r.accuracy) } else { format!("{}: Score {} | CPM {} | Acc {:.1}%", label, agg.score as i64, agg.cpm as i64, agg.accuracy) }
    };
    let today_line = fmt_best("Today's Best", &today);
    if is_new_pb { lines.push(Line::from(Span::styled(format!("*** NEW PB!  {}", today_line), s_rgb(pal.status_warning)))); }
    else { lines.push(Line::from(Span::styled(today_line, s_rgb(pal.text)))); }
    lines.push(Line::from(Span::styled(fmt_best("Weekly Best", &weekly), s_rgb(pal.text))));
    lines.push(Line::from(Span::styled(fmt_best("All time Best", &alltime), s_rgb(pal.text))));
    let repo_disp = app.repo_info.as_ref().map(|i| i.display()).unwrap_or_else(|| "local/unknown".to_string());
    lines.push(Line::from(Span::styled(format!("Stage Results: [{}]", repo_disp), s_rgb(pal.text))));
    lines.push(Line::from(""));
    if let Some(sess) = &app.session {
        for o in sess.outcomes.iter().filter(|o| !o.was_skipped) {
            lines.push(Line::from(Span::styled(format!("{}:", o.challenge.file_path), s_rgb(pal.text))));
            lines.push(Line::from(Span::styled(format!("Score: {} | CPM: {} | Acc: {:.1}%", o.score as i64, o.cpm as i64, o.accuracy), s_rgb(pal.text))));
        }
    }
    lines.push(Line::from(""));
    lines.push(Line::from(vec![key_span(&pal, "back", "[ESC]"), Span::styled(" Return", s_rgb(pal.text))]));
    draw_centered_lines(f, area, lines);
}

