        0 => recs.sort_by(|a, b| b.started_at.cmp(&a.started_at)),
        1 => recs.sort_by(|a, b| b.score.partial_cmp(&a.score).unwrap_or(std::cmp::Ordering::Equal)),
        2 => recs.sort_by(|a, b| b.repo_display.cmp(&a.repo_display)),
        3 => recs.sort_by(|a, b| b.duration_ms.cmp(&a.duration_ms)),
        4 => recs.sort_by(|a, b| a.started_at.cmp(&b.started_at)),
        5 => recs.sort_by(|a, b| a.score.partial_cmp(&b.score).unwrap_or(std::cmp::Ordering::Equal)),
        6 => recs.sort_by(|a, b| a.repo_display.cmp(&b.repo_display)),
        7 => recs.sort_by(|a, b| a.duration_ms.cmp(&b.duration_ms)),
        _ => {}
    }
    recs
}

fn draw_records(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    let recs = filtered_sorted_records(app);
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(4), Constraint::Min(0), Constraint::Length(1)]).split(area);
    let header_block = bordered_block("Session Records", &pal);
    let header_lines = vec![
        Line::from(Span::styled("  Records - Typing Session Records", s_rgb(pal.text))),
        Line::from(Span::styled(format!("  Filter: {} | Sort: {} | Sessions: {}", records_filter_name(app.records_filter_idx), records_sort_name(app.records_sort_idx), recs.len()), s_rgb(pal.text))),
    ];
    f.render_widget(Paragraph::new(header_lines).block(header_block), chunks[0]);
    let sessions_block = bordered_block("Sessions", &pal);
    let inner = sessions_block.inner(chunks[1]);
    f.render_widget(sessions_block, chunks[1]);
