            let marker = if idx == app.records_selected { "▶ " } else { "  " };
            let text = format!("{}{} {:<28.28}{} {:.1} {:.1}%  {}/{}     {}", marker, date_disp, r.repo_display, r.score as i64, r.cpm, r.accuracy, r.stages_completed, r.stages_attempted, format_duration_ms(r.duration_ms));
            let style = if idx == app.records_selected { Style::default().fg(pal.text) } else { s_rgb(pal.text) };
            f.render_widget(Paragraph::new(Line::from(Span::styled(text, style))), Rect::new(inner.x, inner.y + row as u16, inner.width, 1));
        }
        // scrollbar
        if recs.len() > 1 {
            let mut sb_state = ScrollbarState::new(recs.len()).position(app.records_selected).viewport_content_length(visible.max(1));
            let sb = Scrollbar::new(ScrollbarOrientation::VerticalRight).begin_symbol(Some("↑")).end_symbol(Some("↓"));
            f.render_stateful_widget(sb, inner, &mut sb_state);
        }
    }
    let footer = Line::from("[↑↓/JK] Navigate  [SPACE] Details  [F] Filter  [S] Sort  [R] Refresh  [ESC] Back");
    f.render_widget(Paragraph::new(footer).alignment(Alignment::Center), chunks[2]);
}

