// ---------- Analytics ----------
#[derive(Debug, Clone, Default)]
struct LangAgg { name: String, canonical: String, stage_count: i64, sum_cpm_list: f64, total_keystrokes: i64, total_mistakes: i64, total_duration: i64, best_cpm: f64, sum_accuracy: f64, best_accuracy: f64 }
#[derive(Debug, Clone, Default)]
struct RepoAgg { display: String, repository_id: i64, sessions: Vec<RecordItem> }

fn analytics_languages(app: &App) -> Vec<LangAgg> {
    let Some(db) = &app.db else { return vec![]; };
    let rows = db.query("SELECT language FROM stage_results GROUP BY language", &[]).unwrap_or_default();
    let mut out = Vec::new();
    for r in rows {
        let lang = r.text(0).unwrap_or_default();
        let stages = db.query("SELECT cpm, keystrokes, mistakes, duration_ms, accuracy FROM stage_results WHERE language = ?", &[Value::Text(lang.clone())]).unwrap_or_default();
        let mut agg = LangAgg { canonical: lang.clone(), name: Language::from_canonical(&lang).map(|l| l.display().to_string()).unwrap_or(lang.clone()), ..Default::default() };
        for s in stages {
            agg.stage_count += 1;
            agg.sum_cpm_list += s.real(0).unwrap_or(0.0);
            agg.total_keystrokes += s.int(1).unwrap_or(0);
            agg.total_mistakes += s.int(2).unwrap_or(0);
            agg.total_duration += s.int(3).unwrap_or(0);
            let cpm = s.real(0).unwrap_or(0.0);
            if cpm > agg.best_cpm { agg.best_cpm = cpm; }
            let acc = s.real(4).unwrap_or(0.0);
            agg.sum_accuracy += acc;
            if acc > agg.best_accuracy { agg.best_accuracy = acc; }
        }
        out.push(agg);
    }
    out.sort_by(|a, b| {
        let av = if a.stage_count>0 { a.sum_cpm_list / a.stage_count as f64 } else {0.0};
        let bv = if b.stage_count>0 { b.sum_cpm_list / b.stage_count as f64 } else {0.0};
        bv.partial_cmp(&av).unwrap_or(std::cmp::Ordering::Equal)
    });
    out
}
fn analytics_repos(app: &App) -> Vec<RepoAgg> {
    let Some(db) = &app.db else { return vec![]; };
    let items = load_repo_items_from_db(db).unwrap_or_default();
    let records = load_records_from_db(db).unwrap_or_default();
    let mut out = Vec::new();
    for item in items {
        let sess: Vec<RecordItem> = records.iter().filter(|r| r.repository_id == item.repository_id).cloned().collect();
        if !sess.is_empty() { out.push(RepoAgg { display: item.display(), repository_id: item.repository_id, sessions: sess }); }
    }
    out.sort_by(|a, b| {
        let av = if a.sessions.is_empty(){0.0}else{a.sessions.iter().map(|s|s.cpm).sum::<f64>()/a.sessions.len() as f64};
        let bv = if b.sessions.is_empty(){0.0}else{b.sessions.iter().map(|s|s.cpm).sum::<f64>()/b.sessions.len() as f64};
        bv.partial_cmp(&av).unwrap_or(std::cmp::Ordering::Equal)
    });
    out
}

