fn draw_analytics_overview(f: &mut Frame, app: &App, area: Rect) {
    let pal = app.palette();
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(5), Constraint::Length(20), Constraint::Min(0)]).split(area);
    // stats last 7 days
    let records_all = app.db.as_ref().and_then(|d| load_records_from_db(d).ok()).unwrap_or_default();
    let cutoff = chrono::Local::now().naive_local() - chrono::Duration::days(7);
    let recs: Vec<&RecordItem> = records_all.iter().filter(|r| chrono::NaiveDateTime::parse_from_str(&r.started_at, "%Y-%m-%d %H:%M:%S").map(|dt| dt >= cutoff).unwrap_or(false)).collect();
    let sessions = recs.len();
    let avg_cpm = if sessions>0 { recs.iter().map(|r| r.cpm).sum::<f64>() / sessions as f64 } else { 0.0 };
    let best_cpm = recs.iter().map(|r| r.cpm).fold(0.0f64, f64::max);
    let avg_acc = if sessions>0 { recs.iter().map(|r| r.accuracy).sum::<f64>() / sessions as f64 } else { 0.0 };
    let total_ms: i64 = recs.iter().map(|r| r.duration_ms).sum();
    let total_hours = total_ms as f64 / 3600000.0;
    let avg_session_min = if sessions>0 { (total_ms as f64 / sessions as f64) / 60000.0 } else { 0.0 };
    let repo_count = {
        let mut set = HashSet::new();
        for r in &recs { set.insert(r.repository_id); }
        set.len()
    };
    let overview_block = bordered_block("Overview (Last 7 days)", &pal);
    let lines = vec![
        Line::from(format!("Sessions: {}  │  Avg CPM: {:.1}  │  Best CPM: {:.1}  │  Avg Accuracy: {:.1}%", sessions, avg_cpm, best_cpm, avg_acc)).alignment(Alignment::Center),
        Line::from(format!("Total Time: {:.1}h  │  Avg Session: {:.1}m  │  Total Mistakes: 0  │  Repositories: {}", total_hours, avg_session_min, repo_count)).alignment(Alignment::Center),
        Line::from(""),
    ];
    f.render_widget(Paragraph::new(lines).block(overview_block), chunks[0]);
    // recent activity
    // compute daily counts last 38 days
    let today = chrono::Local::now().date_naive();
    let mut daily: Vec<(chrono::NaiveDate, i64)> = Vec::new();
    for i in (0..38).rev() {
        let d = today - chrono::Duration::days(i);
        let cnt = records_all.iter().filter(|r| r.started_at.starts_with(&d.format("%Y-%m-%d").to_string())).count() as i64;
        daily.push((d, cnt));
    }
    let total_sessions: i64 = daily.iter().map(|(_, c)| *c).sum();
    let max_day = daily.iter().map(|(_, c)| *c).max().unwrap_or(0);
    let activity_title = format!("Recent Activity - 38 Days | {} Total Sessions | Max: {}/Day", total_sessions, max_day);
    let activity_block = bordered_block(&activity_title, &pal);
    let inner = activity_block.inner(chunks[1]);
    f.render_widget(activity_block, chunks[1]);
    if inner.height >= 2 {
        let graph_rows = inner.height - 1;
        for (idx, (_d, cnt)) in daily.iter().enumerate() {
            if *cnt == 0 || max_day == 0 { continue; }
            let bar_h = ((*cnt as f64 / max_day as f64) * graph_rows as f64).ceil() as u16;
            let x = inner.x + (idx as u16) * 3;
            if x + 1 >= inner.x + inner.width { continue; }
            for r in 0..bar_h {
                let y = inner.y + graph_rows - 1 - r;
                let cell_text = if r == 0 && *cnt < 10 { format!("{}█", cnt) } else { "██".to_string() };
                // value label 'cnt' replaces first block at bottom row as in original
                f.render_widget(Paragraph::new(Line::from(Span::styled(cell_text, s_rgb(pal.status_success)))), Rect::new(x, y, 2, 1));
            }
        }
        let label_y = inner.y + graph_rows;
        let labels: String = daily.iter().map(|(d, _)| d.format("%d").to_string()).collect::<Vec<_>>().join(" ");
        f.render_widget(Paragraph::new(Line::from(Span::styled(labels, s_rgb(pal.text)))), Rect::new(inner.x, label_y, inner.width, 1));
    }
    // bottom top lists
    let cols = Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage(50), Constraint::Percentage(50)]).split(chunks[2]);
    let repos = analytics_repos(app);
    let repo_block = bordered_block("Top Repositories (Last 90 Days)", &pal);
    let mut repo_lines: Vec<Line> = Vec::new();
    for (i, repo) in repos.iter().take(5).enumerate() {
        let avg = if repo.sessions.is_empty(){0.0}else{repo.sessions.iter().map(|s|s.cpm).sum::<f64>()/repo.sessions.len() as f64};
        repo_lines.push(Line::from(Span::styled(format!("  {}. {:<38}{:.1} CPM", i + 1, repo.display, avg), s_rgb(pal.text))));
    }
    f.render_widget(Paragraph::new(repo_lines).block(repo_block), cols[0]);
    let langs = analytics_languages(app);
    let lang_block = bordered_block("Top Languages (Last 90 Days)", &pal);
    let mut lang_lines: Vec<Line> = Vec::new();
    for (i, lang) in langs.iter().take(5).enumerate() {
        let avg = if lang.stage_count>0 { lang.sum_cpm_list / lang.stage_count as f64 } else {0.0};
        lang_lines.push(Line::from(Span::styled(format!("  {}. {:<38}{:.1} CPM", i + 1, lang.name, avg), s_rgb(pal.text))));
    }
    f.render_widget(Paragraph::new(lang_lines).block(lang_block), cols[1]);
}

fn draw_analytics_trends(f: &mut Frame, app: &App, area: Rect) {
    let pal = app.palette();
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Percentage(50), Constraint::Percentage(50)]).split(area);
    // data by day from session results
    let records = app.db.as_ref().and_then(|d| load_records_from_db(d).ok()).unwrap_or_default();
    // group by date ascending
    let mut by_day: std::collections::BTreeMap<String, Vec<RecordItem>> = std::collections::BTreeMap::new();
    for r in records { by_day.entry(r.started_at[0..10.min(r.started_at.len())].to_string()).or_default().push(r.clone()); }
    let mut cpm_points: Vec<(f64, f64)> = Vec::new();
    let mut acc_points: Vec<(f64, f64)> = Vec::new();
    for (i, (_d, v)) in by_day.iter().enumerate() {
        let acpm = v.iter().map(|x| x.cpm).sum::<f64>() / v.len() as f64;
        let aacc = v.iter().map(|x| x.accuracy).sum::<f64>() / v.len() as f64;
        cpm_points.push((i as f64, acpm));
        acc_points.push((i as f64, aacc));
    }
    if cpm_points.is_empty() { cpm_points.push((0.0, 0.0)); acc_points.push((0.0, 0.0)); }
    let make_chart = |points: &Vec<(f64, f64)>, title: &str, name: &str, y_label_fmt: &dyn Fn(f64) -> String, area: Rect, f: &mut Frame| {
        let max_x = points.iter().map(|p| p.0).fold(1.0f64, f64::max);
        let max_y = points.iter().map(|p| p.1).fold(0.0f64, f64::max);
        let min_y = points.iter().map(|p| p.1).fold(f64::MAX, f64::min);
        let (y0, y1) = if (max_y - min_y).abs() < 0.01 { (min_y, max_y) } else { (min_y, max_y) };
        let dataset = Dataset::default().name(name.to_string()).data(points).graph_type(GraphType::Line).style(s_rgb(pal.status_info));
        let x_axis = Axis::default().title("Date").bounds([0.0, max_x]).style(s_rgb(pal.text_secondary));
        let y_labels = vec![Span::raw(y_label_fmt(y0)), Span::raw(y_label_fmt((y0 + y1) / 2.0)), Span::raw(y_label_fmt(y1))];
        let y_axis = Axis::default().title(name.to_string()).labels(y_labels).bounds([y0, y1]).style(s_rgb(pal.text_secondary));
        let chart = Chart::new(vec![dataset]).block(bordered_block(title, &pal)).x_axis(x_axis).y_axis(y_axis);
        f.render_widget(chart, area);
    };
    make_chart(&cpm_points, "CPM Performance Trend", "CPM", &|v| format!("{}", v.round() as i64), chunks[0], f);
    make_chart(&acc_points, "Accuracy Performance Trend", "Accuracy", &|v| format!("{:.1}%", v), chunks[1], f);
}

