// ---------- Records ----------
fn records_filter_name(idx: usize) -> &'static str { match idx { 0=>"Last 30 days", 1=>"Last 90 days", 2=>"All Time", 3=>"Last 7 days", _=>"Last 30 days" } }
fn records_sort_name(idx: usize) -> String {
    match idx { 0=>"Date ↓", 1=>"Score ↓", 2=>"Repository ↓", 3=>"Duration ↓", 4=>"Date ↑", 5=>"Score ↑", 6=>"Repository ↑", 7=>"Duration ↑", _=>"Date ↓" }.to_string()
}
fn filtered_sorted_records(app: &App) -> Vec<RecordItem> {
    let mut recs = app.records.clone();
    // filter
    let days: Option<i64> = match app.records_filter_idx { 0=>Some(30), 1=>Some(90), 2=>None, 3=>Some(7), _=>Some(30) };
    if let Some(d) = days {
        let cutoff = chrono::Local::now().naive_local() - chrono::Duration::days(d);
        recs.retain(|r| {
            if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(&r.started_at, "%Y-%m-%d %H:%M:%S") { dt >= cutoff } else { true }
        });
    }
    match app.records_sort_idx {
        0 => recs.sort_by(|a, b| b.started_at.cmp(&a.started_at)),
        1 => recs.sort_by(|a, b| b.score.partial_cmp(&a.score).unwrap_or(std::cmp::Ordering::Equal)),
        2 => recs.sort_by(|a, b| b.repo_display.cmp(&a.repo_display)),
        3 => recs.sort_by(|a, b| b.duration_ms.cmp(&a.duration_ms)),
        4 => recs.sort_by(|a, b| a.started_at.cmp(&b.started_at)),
        5 => recs.sort_by(|a, b| a.score.partial_cmp(&b.score).unwrap_or(std::cmp::Ordering::Equal)),
        6 => recs.sort_by(|a, b| a.repo_display.cmp(&b.repo_display)),
        7 => recs.sort_by(|a, b| a.duration_ms.cmp(&b.duration_ms)),
        _ => {}
    }
    recs
}

fn draw_records(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    let recs = filtered_sorted_records(app);
