        Line::from(Span::styled("  Records - Typing Session Records", s_rgb(pal.text))),
        Line::from(Span::styled(format!("  Filter: {} | Sort: {} | Sessions: {}", records_filter_name(app.records_filter_idx), records_sort_name(app.records_sort_idx), recs.len()), s_rgb(pal.text))),
    ];
    f.render_widget(Paragraph::new(header_lines).block(header_block), chunks[0]);
    let sessions_block = bordered_block("Sessions", &pal);
    let inner = sessions_block.inner(chunks[1]);
    f.render_widget(sessions_block, chunks[1]);
    if recs.is_empty() {
        let lines = vec![
            Line::from(Span::styled("No typing sessions found for the selected time period.", s_rgb(pal.text))).alignment(Alignment::Center),
            Line::from(Span::styled("Start typing to build your records!", s_rgb(pal.text))).alignment(Alignment::Center),
        ];
        f.render_widget(Paragraph::new(lines), inner);
    } else {
        let visible = inner.height as usize;
        let mut start = 0usize;
        if app.records_selected >= visible && visible > 0 { start = app.records_selected + 1 - visible; }
        for (row, idx) in (start..recs.len()).enumerate() {
