fn repo_detail_sums(app: &App, repo_id: i64) -> (i64, i64, i64, i64, i64) {
    let Some(db) = &app.db else { return (0,0,0,0,0); };
    let rows = db.query("SELECT SUM(keystrokes), SUM(mistakes), SUM(duration_ms), SUM(stages_completed), SUM(stages_attempted) FROM session_results WHERE repository_id = ?", &[Value::Int(repo_id)]).unwrap_or_default();
    if let Some(r) = rows.get(0) { (r.int(0).unwrap_or(0), r.int(1).unwrap_or(0), r.int(2).unwrap_or(0), r.int(3).unwrap_or(0), r.int(4).unwrap_or(0)) } else { (0,0,0,0,0) }
}

