// ---------- Analytics ----------
#[derive(Debug, Clone, Default)]
struct LangAgg { name: String, canonical: String, stage_count: i64, sum_cpm_list: f64, total_keystrokes: i64, total_mistakes: i64, total_duration: i64, best_cpm: f64, sum_accuracy: f64, best_accuracy: f64 }
#[derive(Debug, Clone, Default)]
struct RepoAgg { display: String, repository_id: i64, sessions: Vec<RecordItem> }

fn analytics_languages(app: &App) -> Vec<LangAgg> {
    let Some(db) = &app.db else { return vec![]; };
    let rows = db.query("SELECT language FROM stage_results GROUP BY language", &[]).unwrap_or_default();
    let mut out = Vec::new();
    for r in rows {
        let lang = r.text(0).unwrap_or_default();
        let stages = db.query("SELECT cpm, keystrokes, mistakes, duration_ms, accuracy FROM stage_results WHERE language = ?", &[Value::Text(lang.clone())]).unwrap_or_default();
        let mut agg = LangAgg { canonical: lang.clone(), name: Language::from_canonical(&lang).map(|l| l.display().to_string()).unwrap_or(lang.clone()), ..Default::default() };
        for s in stages {
            agg.stage_count += 1;
            agg.sum_cpm_list += s.real(0).unwrap_or(0.0);
            agg.total_keystrokes += s.int(1).unwrap_or(0);
            agg.total_mistakes += s.int(2).unwrap_or(0);
            agg.total_duration += s.int(3).unwrap_or(0);
            let cpm = s.real(0).unwrap_or(0.0);
            if cpm > agg.best_cpm { agg.best_cpm = cpm; }
            let acc = s.real(4).unwrap_or(0.0);
            agg.sum_accuracy += acc;
            if acc > agg.best_accuracy { agg.best_accuracy = acc; }
        }
        out.push(agg);
    }
    out.sort_by(|a, b| {
        let av = if a.stage_count>0 { a.sum_cpm_list / a.stage_count as f64 } else {0.0};
        let bv = if b.stage_count>0 { b.sum_cpm_list / b.stage_count as f64 } else {0.0};
        bv.partial_cmp(&av).unwrap_or(std::cmp::Ordering::Equal)
    });
    out
}
fn analytics_repos(app: &App) -> Vec<RepoAgg> {
    let Some(db) = &app.db else { return vec![]; };
    let items = load_repo_items_from_db(db).unwrap_or_default();
    let records = load_records_from_db(db).unwrap_or_default();
    let mut out = Vec::new();
    for item in items {
        let sess: Vec<RecordItem> = records.iter().filter(|r| r.repository_id == item.repository_id).cloned().collect();
        if !sess.is_empty() { out.push(RepoAgg { display: item.display(), repository_id: item.repository_id, sessions: sess }); }
    }
    out.sort_by(|a, b| {
        let av = if a.sessions.is_empty(){0.0}else{a.sessions.iter().map(|s|s.cpm).sum::<f64>()/a.sessions.len() as f64};
        let bv = if b.sessions.is_empty(){0.0}else{b.sessions.iter().map(|s|s.cpm).sum::<f64>()/b.sessions.len() as f64};
        bv.partial_cmp(&av).unwrap_or(std::cmp::Ordering::Equal)
    });
    out
}

fn draw_analytics(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(3), Constraint::Length(3), Constraint::Min(0), Constraint::Length(1)]).split(area);
    // header
    let header_block = bordered_block("GitType Analytics", &pal);
    f.render_widget(Paragraph::new(Line::from(Span::styled("  Performance Analytics", s_rgb(pal.text)))).block(header_block), chunks[0]);
    // views
    let views_block = bordered_block("Views", &pal);
    let tab_names = ["Overview", "Trends", "Repositories", "Languages"];
    let mut spans: Vec<Span> = Vec::new();
    spans.push(Span::raw("  "));
    for (i, name) in tab_names.iter().enumerate() {
        let style = if i == app.analytics_tab { Style::default().fg(pal.text).add_modifier(Modifier::BOLD) } else { s_rgb(pal.text) };
        spans.push(Span::styled(name.to_string(), style));
        if i + 1 < tab_names.len() { spans.push(Span::raw(" | ")); }
    }
    f.render_widget(Paragraph::new(Line::from(spans)).block(views_block), chunks[1]);
    let content = chunks[2];
    match app.analytics_tab {
        0 => draw_analytics_overview(f, app, content),
        1 => draw_analytics_trends(f, app, content),
        2 => draw_analytics_repos(f, app, content),
        _ => draw_analytics_languages(f, app, content),
    }
    let footer = Line::from("[←→/HL] Switch View  [↑↓/JK] Navigate  [R] Refresh  [ESC] Back");
    f.render_widget(Paragraph::new(footer).alignment(Alignment::Center), chunks[3]);
}

fn draw_analytics_overview(f: &mut Frame, app: &App, area: Rect) {
    let pal = app.palette();
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(5), Constraint::Length(20), Constraint::Min(0)]).split(area);
    // stats last 7 days
    let records_all = app.db.as_ref().and_then(|d| load_records_from_db(d).ok()).unwrap_or_default();
    let cutoff = chrono::Local::now().naive_local() - chrono::Duration::days(7);
    let recs: Vec<&RecordItem> = records_all.iter().filter(|r| chrono::NaiveDateTime::parse_from_str(&r.started_at, "%Y-%m-%d %H:%M:%S").map(|dt| dt >= cutoff).unwrap_or(false)).collect();
    let sessions = recs.len();
    let avg_cpm = if sessions>0 { recs.iter().map(|r| r.cpm).sum::<f64>() / sessions as f64 } else { 0.0 };
    let best_cpm = recs.iter().map(|r| r.cpm).fold(0.0f64, f64::max);
    let avg_acc = if sessions>0 { recs.iter().map(|r| r.accuracy).sum::<f64>() / sessions as f64 } else { 0.0 };
    let total_ms: i64 = recs.iter().map(|r| r.duration_ms).sum();
    let total_hours = total_ms as f64 / 3600000.0;
    let avg_session_min = if sessions>0 { (total_ms as f64 / sessions as f64) / 60000.0 } else { 0.0 };
    let repo_count = {
        let mut set = HashSet::new();
        for r in &recs { set.insert(r.repository_id); }
        set.len()
    };
    let overview_block = bordered_block("Overview (Last 7 days)", &pal);
    let lines = vec![
        Line::from(format!("Sessions: {}  │  Avg CPM: {:.1}  │  Best CPM: {:.1}  │  Avg Accuracy: {:.1}%", sessions, avg_cpm, best_cpm, avg_acc)).alignment(Alignment::Center),
        Line::from(format!("Total Time: {:.1}h  │  Avg Session: {:.1}m  │  Total Mistakes: 0  │  Repositories: {}", total_hours, avg_session_min, repo_count)).alignment(Alignment::Center),
        Line::from(""),
    ];
    f.render_widget(Paragraph::new(lines).block(overview_block), chunks[0]);
    // recent activity
    // compute daily counts last 38 days
    let today = chrono::Local::now().date_naive();
    let mut daily: Vec<(chrono::NaiveDate, i64)> = Vec::new();
    for i in (0..38).rev() {
        let d = today - chrono::Duration::days(i);
        let cnt = records_all.iter().filter(|r| r.started_at.starts_with(&d.format("%Y-%m-%d").to_string())).count() as i64;
        daily.push((d, cnt));
    }
    let total_sessions: i64 = daily.iter().map(|(_, c)| *c).sum();
    let max_day = daily.iter().map(|(_, c)| *c).max().unwrap_or(0);
    let activity_title = format!("Recent Activity - 38 Days | {} Total Sessions | Max: {}/Day", total_sessions, max_day);
    let activity_block = bordered_block(&activity_title, &pal);
    let inner = activity_block.inner(chunks[1]);
    f.render_widget(activity_block, chunks[1]);
    if inner.height >= 2 {
        let graph_rows = inner.height - 1;
        for (idx, (_d, cnt)) in daily.iter().enumerate() {
            if *cnt == 0 || max_day == 0 { continue; }
            let bar_h = ((*cnt as f64 / max_day as f64) * graph_rows as f64).ceil() as u16;
            let x = inner.x + (idx as u16) * 3;
            if x + 1 >= inner.x + inner.width { continue; }
            for r in 0..bar_h {
                let y = inner.y + graph_rows - 1 - r;
                let cell_text = if r == 0 && *cnt < 10 { format!("{}█", cnt) } else { "██".to_string() };
                // value label 'cnt' replaces first block at bottom row as in original
                f.render_widget(Paragraph::new(Line::from(Span::styled(cell_text, s_rgb(pal.status_success)))), Rect::new(x, y, 2, 1));
            }
        }
        let label_y = inner.y + graph_rows;
        let labels: String = daily.iter().map(|(d, _)| d.format("%d").to_string()).collect::<Vec<_>>().join(" ");
        f.render_widget(Paragraph::new(Line::from(Span::styled(labels, s_rgb(pal.text)))), Rect::new(inner.x, label_y, inner.width, 1));
    }
    // bottom top lists
    let cols = Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage(50), Constraint::Percentage(50)]).split(chunks[2]);
    let repos = analytics_repos(app);
    let repo_block = bordered_block("Top Repositories (Last 90 Days)", &pal);
    let mut repo_lines: Vec<Line> = Vec::new();
    for (i, repo) in repos.iter().take(5).enumerate() {
        let avg = if repo.sessions.is_empty(){0.0}else{repo.sessions.iter().map(|s|s.cpm).sum::<f64>()/repo.sessions.len() as f64};
        repo_lines.push(Line::from(Span::styled(format!("  {}. {:<38}{:.1} CPM", i + 1, repo.display, avg), s_rgb(pal.text))));
    }
    f.render_widget(Paragraph::new(repo_lines).block(repo_block), cols[0]);
    let langs = analytics_languages(app);
    let lang_block = bordered_block("Top Languages (Last 90 Days)", &pal);
    let mut lang_lines: Vec<Line> = Vec::new();
    for (i, lang) in langs.iter().take(5).enumerate() {
        let avg = if lang.stage_count>0 { lang.sum_cpm_list / lang.stage_count as f64 } else {0.0};
        lang_lines.push(Line::from(Span::styled(format!("  {}. {:<38}{:.1} CPM", i + 1, lang.name, avg), s_rgb(pal.text))));
    }
    f.render_widget(Paragraph::new(lang_lines).block(lang_block), cols[1]);
}

fn draw_analytics_trends(f: &mut Frame, app: &App, area: Rect) {
    let pal = app.palette();
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Percentage(50), Constraint::Percentage(50)]).split(area);
    // data by day from session results
    let records = app.db.as_ref().and_then(|d| load_records_from_db(d).ok()).unwrap_or_default();
    // group by date ascending
    let mut by_day: std::collections::BTreeMap<String, Vec<RecordItem>> = std::collections::BTreeMap::new();
    for r in records { by_day.entry(r.started_at[0..10.min(r.started_at.len())].to_string()).or_default().push(r.clone()); }
    let mut cpm_points: Vec<(f64, f64)> = Vec::new();
    let mut acc_points: Vec<(f64, f64)> = Vec::new();
    for (i, (_d, v)) in by_day.iter().enumerate() {
        let acpm = v.iter().map(|x| x.cpm).sum::<f64>() / v.len() as f64;
        let aacc = v.iter().map(|x| x.accuracy).sum::<f64>() / v.len() as f64;
        cpm_points.push((i as f64, acpm));
        acc_points.push((i as f64, aacc));
    }
    if cpm_points.is_empty() { cpm_points.push((0.0, 0.0)); acc_points.push((0.0, 0.0)); }
    let make_chart = |points: &Vec<(f64, f64)>, title: &str, name: &str, y_label_fmt: &dyn Fn(f64) -> String, area: Rect, f: &mut Frame| {
        let max_x = points.iter().map(|p| p.0).fold(1.0f64, f64::max);
        let max_y = points.iter().map(|p| p.1).fold(0.0f64, f64::max);
        let min_y = points.iter().map(|p| p.1).fold(f64::MAX, f64::min);
        let (y0, y1) = if (max_y - min_y).abs() < 0.01 { (min_y, max_y) } else { (min_y, max_y) };
        let dataset = Dataset::default().name(name.to_string()).data(points).graph_type(GraphType::Line).style(s_rgb(pal.status_info));
        let x_axis = Axis::default().title("Date").bounds([0.0, max_x]).style(s_rgb(pal.text_secondary));
        let y_labels = vec![Span::raw(y_label_fmt(y0)), Span::raw(y_label_fmt((y0 + y1) / 2.0)), Span::raw(y_label_fmt(y1))];
        let y_axis = Axis::default().title(name.to_string()).labels(y_labels).bounds([y0, y1]).style(s_rgb(pal.text_secondary));
        let chart = Chart::new(vec![dataset]).block(bordered_block(title, &pal)).x_axis(x_axis).y_axis(y_axis);
        f.render_widget(chart, area);
    };
    make_chart(&cpm_points, "CPM Performance Trend", "CPM", &|v| format!("{}", v.round() as i64), chunks[0], f);
    make_chart(&acc_points, "Accuracy Performance Trend", "Accuracy", &|v| format!("{:.1}%", v), chunks[1], f);
}

fn draw_analytics_repos(f: &mut Frame, app: &App, area: Rect) {
    let pal = app.palette();
    let cols = Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage(38), Constraint::Percentage(62)]).split(area);
    let repos = analytics_repos(app);
    let list_block = bordered_block("Repositories", &pal);
    let inner = list_block.inner(cols[0]);
    f.render_widget(list_block, cols[0]);
    let visible = inner.height as usize;
    for (i, repo) in repos.iter().enumerate() {
        if i >= visible { break; }
        let avg = if repo.sessions.is_empty(){0.0}else{repo.sessions.iter().map(|s|s.cpm).sum::<f64>()/repo.sessions.len() as f64};
        let marker = if i == app.analytics_repo_selected { "► " } else { "  " };
        let text = format!("{}{} {:.1} CPM ({} sessions)", marker, repo.display, avg, repo.sessions.len());
        f.render_widget(Paragraph::new(Line::from(Span::styled(text, s_rgb(pal.text)))), Rect::new(inner.x, inner.y + i as u16, inner.width, 1));
    }
    if repos.len() > 1 {
        let mut sb_state = ScrollbarState::new(repos.len()).position(app.analytics_repo_selected).viewport_content_length(visible.max(1));
        f.render_stateful_widget(Scrollbar::new(ScrollbarOrientation::VerticalRight).begin_symbol(Some("↑")).end_symbol(Some("↓")), inner, &mut sb_state);
    }
    let detail_block = bordered_block("Repository Details (Last 90 Days)", &pal);
    let mut lines: Vec<Line> = Vec::new();
    if let Some(repo) = repos.get(app.analytics_repo_selected) {
        let sess = &repo.sessions;
        let avg_cpm = if sess.is_empty(){0.0}else{sess.iter().map(|s|s.cpm).sum::<f64>()/sess.len() as f64};
        let avg_wpm = if sess.is_empty(){0.0}else{sess.iter().map(|s|s.wpm).sum::<f64>()/sess.len() as f64};
        // details weighted etc from db sums
        let (total_keys, total_mist, total_ms, sc, sa) = repo_detail_sums(app, repo.repository_id);
        let best_cpm = sess.iter().map(|s| s.cpm).fold(0.0f64, f64::max);
        let avg_acc = if sess.is_empty(){0.0}else{sess.iter().map(|s|s.accuracy).sum::<f64>()/sess.len() as f64};
        let best_acc = sess.iter().map(|s| s.accuracy).fold(0.0f64, f64::max);
        let weighted_cpm = {
            // use sums from stage? For repo details original used session avg (368.3) - use avg_cpm for score calc
            avg_cpm
        };
        let avg_score = (weighted_cpm * avg_acc / 100.0).round() as i64;
        lines.push(Line::from(Span::styled(format!("  Repository: {}", repo.display), s_rgb(pal.text))));
        lines.push(Line::from(""));
        lines.push(Line::from(Span::styled("  📈 Speed Metrics:", s_rgb(pal.text))));
        lines.push(Line::from(Span::styled(format!("    • Average CPM: {:.1}", avg_cpm), s_rgb(pal.text))));
        lines.push(Line::from(Span::styled(format!("    • Average WPM: {:.1}", avg_wpm), s_rgb(pal.text))));
        lines.push(Line::from(Span::styled(format!("    • Best CPM: {:.1}", best_cpm), s_rgb(pal.text))));
        lines.push(Line::from(""));
        lines.push(Line::from(Span::styled("  🎯 Accuracy & Quality:", s_rgb(pal.text))));
        lines.push(Line::from(Span::styled(format!("    • Average Accuracy: {:.1}%", avg_acc), s_rgb(pal.text))));
        lines.push(Line::from(Span::styled(format!("    • Best Accuracy: {:.1}%", best_acc), s_rgb(pal.text))));
        lines.push(Line::from(Span::styled(format!("    • Total Mistakes: {}", total_mist), s_rgb(pal.text))));
        lines.push(Line::from(""));
        lines.push(Line::from(Span::styled("  📊 Volume & Activity:", s_rgb(pal.text))));
        lines.push(Line::from(Span::styled(format!("    • Total Sessions: {}", sess.len()), s_rgb(pal.text))));
        lines.push(Line::from(Span::styled(format!("    • Total Keystrokes: {}", total_keys), s_rgb(pal.text))));
        lines.push(Line::from(Span::styled(format!("    • Total Time: {}", format_time_hm(total_ms)), s_rgb(pal.text))));
        lines.push(Line::from(""));
        lines.push(Line::from(Span::styled("  🏆 Progress:", s_rgb(pal.text))));
        lines.push(Line::from(Span::styled(format!("    • Average Score: {}", avg_score), s_rgb(pal.text))));
        lines.push(Line::from(Span::styled(format!("    • Total Stages: {}/{} completed", sc, sa), s_rgb(pal.text))));
    }
    f.render_widget(Paragraph::new(lines).block(detail_block), cols[1]);
}

fn repo_detail_sums(app: &App, repo_id: i64) -> (i64, i64, i64, i64, i64) {
    let Some(db) = &app.db else { return (0,0,0,0,0); };
    let rows = db.query("SELECT SUM(keystrokes), SUM(mistakes), SUM(duration_ms), SUM(stages_completed), SUM(stages_attempted) FROM session_results WHERE repository_id = ?", &[Value::Int(repo_id)]).unwrap_or_default();
    if let Some(r) = rows.get(0) { (r.int(0).unwrap_or(0), r.int(1).unwrap_or(0), r.int(2).unwrap_or(0), r.int(3).unwrap_or(0), r.int(4).unwrap_or(0)) } else { (0,0,0,0,0) }
}

