// ---------- Help ----------
pub fn help_tabs() -> [&'static str; 7] { ["CLI Usage", "Scoring System", "Rank System", "Game Help", "Community", "About & Credits", "Third-Party Licenses"] }
pub fn help_content(tab: usize) -> Vec<String> {
    let raw: String = match tab {
        0 => include_str!("../assets/help_cli.txt").to_string(),
        1 => "Score Calculation Formula:\n\nBase Score = CPM × (Accuracy / 100) × 10\n\nCPM (Characters Per Minute): Total characters typed / minutes\nWPM (Words Per Minute): CPM / 5 (average word length)\nAccuracy: (Total chars - Mistakes) / Total chars × 100%\n\nBonuses & Penalties:\n\n• Consistency Bonus: Up to 70% extra for high accuracy\n• Time Bonus: Extra points for fast completion\n• Mistake Penalty: -5 points per error\n\nFinal Score = (Base + Consistency + Time - Penalties) × 2 + 100".to_string(),
        2 => include_str!("../assets/help_rank.txt").to_string(),
        3 => include_str!("../assets/help_game.txt").to_string(),
        4 => include_str!("../assets/help_community.txt").to_string(),
        5 => "GitType\n\nA CLI code-typing game that turns your source code into typing challenges\n\nPractice typing with your own code repositories -\nimprove your speed and accuracy while working with\nreal functions, classes, and methods from your actual projects.\n\nDevelopment Team:\n\n• Creator & Lead Developer: unhappychoice\n\nSpecial Thanks:\n\n• All open-source repository maintainers\n• The Rust community for excellent tooling\n• Tree-sitter for code parsing capabilities\n• Ratatui for terminal UI framework\n• All contributors and users providing feedback\n\nBuilt with:\n\n• Rust - Systems programming language\n• Ratatui - Terminal user interface library\n• Tree-sitter - Code parsing and syntax highlighting\n• SQLite - Local data storage\n• Git2 - Repository cloning and management".to_string(),
        6 => {
            let lic = include_str!("../LICENSE-THIRD-PARTY");
            lic.to_string()
        }
        _ => String::new(),
    };
    raw.lines().map(|s| s.to_string()).collect()
}

fn draw_help(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    if app.help_github_popup {
        // only popup
        let width = 60u16.min(area.width);
        let height = 9u16.min(area.height);
        let x = area.x + area.width.saturating_sub(width) / 2;
        let y = area.y + area.height.saturating_sub(height) / 2;
        let rect = Rect::new(x, y, width, height);
        let block = Block::default().borders(Borders::ALL).border_style(s_rgb(pal.border)).title("Cannot open GitHub").title_alignment(Alignment::Center);
        let lines = vec![
            Line::from(""),
            Line::from(Span::styled("Please copy and paste the URL below:", s_rgb(pal.text))).alignment(Alignment::Center),
            Line::from(Span::styled("https://github.com/unhappychoice/gittype", s_rgb(pal.status_info))).alignment(Alignment::Center),
            Line::from(""),
            Line::from(Span::styled("[ESC] Back", s_rgb(pal.text))).alignment(Alignment::Center),
            Line::from(""),
        ];
        f.render_widget(Paragraph::new(lines).block(block), rect);
        return;
    }
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(3), Constraint::Min(0), Constraint::Length(4)]).split(area);
    let header_block = bordered_block("Help", &pal);
    let tabs = help_tabs();
    let mut spans: Vec<Span> = Vec::new();
    spans.push(Span::raw(" "));
    for (i, name) in tabs.iter().enumerate() {
        let style = if i == app.help_tab { Style::default().fg(pal.text).add_modifier(Modifier::BOLD) } else { Style::default() };
        spans.push(Span::styled(name.to_string(), style));
        if i + 1 < tabs.len() { spans.push(Span::raw(" │ ")); }
    }
    f.render_widget(Paragraph::new(Line::from(spans)).block(header_block), chunks[0]);
    let content_block = bordered_block_plain(&pal);
    let inner = content_block.inner(chunks[1]);
    f.render_widget(content_block, chunks[1]);
    let content = help_content(app.help_tab);
    let mut lines: Vec<Line> = Vec::new();
    for l in &content {
        if l.is_empty() { lines.push(Line::from("")); } else { lines.push(Line::from(Span::styled(format!("  {}", l), s_rgb(pal.text)))); }
    }
    let viewport = inner.height as usize;
    let max_scroll = if lines.len() > viewport { lines.len() - viewport } else { 0 };
    let scroll = (app.help_scroll as usize).min(max_scroll);
    f.render_widget(Paragraph::new(lines.clone()).scroll((scroll as u16, 0)).wrap(Wrap { trim: false }), inner);
    // scrollbar on right border
    if lines.len() > viewport {
        let sb_area = Rect::new(chunks[1].x + chunks[1].width.saturating_sub(1), chunks[1].y, 1, chunks[1].height);
        let mut state = ScrollbarState::new(lines.len()).position(scroll).viewport_content_length(viewport);
        let sb = Scrollbar::new(ScrollbarOrientation::VerticalRight).symbols(symbols::scrollbar::VERTICAL).begin_symbol(Some("▲")).end_symbol(Some("▼")).track_symbol(Some("║")).thumb_symbol("█");
        f.render_stateful_widget(sb, sb_area, &mut state);
    }
    // footer
    let footer_lines = vec![
        Line::from(""),
        Line::from(Span::styled("★ Star us on GitHub (https://github.com/unhappychoice/gittype) if you enjoy GitType! ★", s_rgb(pal.status_warning))).alignment(Alignment::Center),
        Line::from(""),
        Line::from(Span::styled("[←→/HL] Switch tabs [↑↓/JK] Scroll [G] GitHub [ESC] Close", s_rgb(pal.text))).alignment(Alignment::Center),
    ];
    f.render_widget(Paragraph::new(footer_lines), chunks[2]);
}

