fn draw_repo_list(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(3), Constraint::Length(3), Constraint::Min(0), Constraint::Length(3), Constraint::Length(1)]).split(area);
    let b1 = bordered_block_plain(&pal);
    f.render_widget(Paragraph::new(Line::from(Span::styled("GitType - Played Repositories", s_rgb(pal.title)))).alignment(Alignment::Center).block(b1), chunks[0]);
    let b2 = bordered_block_plain(&pal);
    let repos_dir = gittype_dir().join("repos");
    f.render_widget(Paragraph::new(Line::from(Span::styled(format!("Cache Directory: {}", repos_dir.display()), s_rgb(pal.text)))).block(b2), chunks[1]);
    let list_block = bordered_block("Repository List", &pal);
    let mut lines: Vec<Line> = Vec::new();
    for item in &app.repo_list_items {
        let cached_mark = if item.cached { "●" } else { "○" };
        let langs = item.languages.join(", ");
        let github_url = format!("https://github.com/{}.git", item.remote_url.trim_end_matches(".git"));
        lines.push(Line::from(Span::styled(format!(" {} {:<35}{:<25}{}", cached_mark, item.display(), langs, github_url), s_rgb(pal.text))));
    }
    f.render_widget(Paragraph::new(lines).block(list_block), chunks[2]);
    let b4 = bordered_block_plain(&pal);
    f.render_widget(Paragraph::new(Line::from(Span::styled("● Cached  ○ Not Cached", s_rgb(pal.text)))).alignment(Alignment::Center).block(b4), chunks[3]);
    f.render_widget(Paragraph::new(Line::from("[ESC] Return")).alignment(Alignment::Center), chunks[4]);
}

fn draw_repo_play(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(2), Constraint::Length(3), Constraint::Min(0), Constraint::Length(1)]).split(area);
    let margin_area = chunks[2];
    // header inside margin x=2
    let header_area = Rect::new(area.x + 2, chunks[1].y, area.width.saturating_sub(4), chunks[1].height);
    let header_block = bordered_block("GitType", &pal);
    f.render_widget(Paragraph::new(Line::from(Span::styled("  Select Repository to Play", s_rgb(pal.text)))).block(header_block), header_area);
    let list_area = Rect::new(area.x + 2, margin_area.y, area.width.saturating_sub(4), margin_area.height);
    let list_block = bordered_block("Played Repositories", &pal);
    let inner = list_block.inner(list_area);
    f.render_widget(list_block, list_area);
    // blank row then items
    for (i, item) in app.repo_list_items.iter().enumerate() {
        let y = inner.y + 1 + i as u16;
        if y >= inner.y + inner.height { break; }
        let cached_mark = if item.cached { "●" } else { "○" };
        let langs = item.languages.join(", ");
        let text = format!("  {} {:<35}{}", cached_mark, item.display(), langs);
        let style = if i == app.repo_play_selected { Style::default().fg(pal.background).bg(pal.text) } else { s_rgb(pal.text) };
        let padded = format!("{:<width$}", text, width = inner.width as usize);
        f.render_widget(Paragraph::new(Line::from(Span::styled(padded, style))), Rect::new(inner.x, y, inner.width, 1));
    }
    let footer_area = chunks[3];
    f.render_widget(Paragraph::new(Line::from("[↑↓/JK] Navigate  [SPACE] Play  [ESC] Return  ● Cached ○ Not Cached")).alignment(Alignment::Center), footer_area);
}

