fn draw_trending_languages(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    let outer = Rect::new(area.x + 2, area.y, area.width.saturating_sub(4), area.height);
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(3), Constraint::Min(0), Constraint::Length(1)]).split(outer);
    let header_block = bordered_block("GitType - Trending Languages", &pal);
    f.render_widget(Paragraph::new(Line::from(Span::styled("  🌏 Select Programming Language", s_rgb(pal.text)))).block(header_block), chunks[0]);
    let list_block = bordered_block("Programming Languages", &pal);
    let inner = list_block.inner(chunks[1]);
    f.render_widget(list_block, chunks[1]);
    for (i, lang) in TRENDING_LANGUAGES.iter().enumerate() {
        let y = inner.y + 1 + i as u16;
        if y >= inner.y + inner.height { break; }
        let text = format!(" {:>2}. {}", i + 1, lang);
        let style = if i == app.trending_language_selected { Style::default().fg(pal.background).bg(pal.text) } else { s_rgb(pal.text) };
        let padded = format!("{:<width$}", text, width = inner.width as usize);
        f.render_widget(Paragraph::new(Line::from(Span::styled(padded, style))), Rect::new(inner.x, y, inner.width, 1));
    }
    f.render_widget(Paragraph::new(Line::from("[↑↓/JK] Navigate  [SPACE] Select  [ESC] Return")).alignment(Alignment::Center), chunks[2]);
}

fn draw_trending_repos(f: &mut Frame, app: &App) {
