// ---------- Repo List ----------
fn draw_repo_list(f: &mut Frame, app: &App) {
    let area = f.area();
    let pal = app.palette();
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(3), Constraint::Length(3), Constraint::Min(0), Constraint::Length(3), Constraint::Length(1)]).split(area);
    let b1 = bordered_block_plain(&pal);
    f.render_widget(Paragraph::new(Line::from(Span::styled("GitType - Played Repositories", s_rgb(pal.title)))).alignment(Alignment::Center).block(b1), chunks[0]);
    let b2 = bordered_block_plain(&pal);
    let repos_dir = gittype_dir().join("repos");
    f.render_widget(Paragraph::new(Line::from(Span::styled(format!("Cache Directory: {}", repos_dir.display()), s_rgb(pal.text)))).block(b2), chunks[1]);
    let list_block = bordered_block("Repository List", &pal);
    let mut lines: Vec<Line> = Vec::new();
    for item in &app.repo_list_items {
        let cached_mark = if item.cached { "●" } else { "○" };
        let langs = item.languages.join(", ");
        let github_url = format!("https://github.com/{}.git", item.remote_url.trim_end_matches(".git"));
        lines.push(Line::from(Span::styled(format!(" {} {:<35}{:<25}{}", cached_mark, item.display(), langs, github_url), s_rgb(pal.text))));
