fn set_total_override_from_result(app: &mut App) {
    // DB aggregates plus duplicate current session (as observed)
    let current = session_aggregate_for_summary(app);
    let db_records = app.db.as_ref().and_then(|d| load_records_from_db(d).ok()).unwrap_or_default();
    let mut sessions = db_records.clone();
    // add duplicate of current session as an extra record-like entry for totals
    // Instead compute directly
    let total_sessions = sessions.len() + 1;
    let mut keystrokes: i64 = 0; let mut mistakes: i64 = 0; let mut skipped: i64 = 0; let mut sc: i64 = 0; let mut sa: i64 = 0; let mut score_sum = 0.0;
    let mut cpm_sum = 0.0; let mut acc_sum = 0.0;
    if let Some(db) = &app.db {
        if let Ok(rows) = db.query("SELECT SUM(keystrokes), SUM(mistakes), SUM(stages_skipped), SUM(stages_completed), SUM(stages_attempted), SUM(score), SUM(cpm), SUM(accuracy) FROM session_results", &[]) {
            if let Some(r) = rows.get(0) {
                keystrokes = r.int(0).unwrap_or(0); mistakes = r.int(1).unwrap_or(0); skipped = r.int(2).unwrap_or(0); sc = r.int(3).unwrap_or(0); sa = r.int(4).unwrap_or(0); score_sum = r.real(5).unwrap_or(0.0); cpm_sum = r.real(6).unwrap_or(0.0); acc_sum = r.real(7).unwrap_or(0.0);
            }
        }
    }
    // duplicate current
    keystrokes += current.keystrokes; mistakes += current.mistakes; skipped += current.stages_skipped; sc += current.stages_completed; sa += current.stages_attempted; score_sum += current.score; cpm_sum += current.cpm; acc_sum += current.accuracy;
    sessions.push(RecordItem { session_result_id: 0, session_id: 0, repository_id: 0, started_at: String::new(), repo_display: String::new(), score: current.score, cpm: current.cpm, wpm: current.wpm, accuracy: current.accuracy, stages_completed: current.stages_completed, stages_attempted: current.stages_attempted, duration_ms: current.duration_ms, branch: None, commit_hash: None });
    let avg_cpm = if total_sessions>0 { cpm_sum / total_sessions as f64 } else {0.0};
    let avg_acc = if total_sessions>0 { acc_sum / total_sessions as f64 } else {0.0};
    let best = sessions.iter().max_by(|a,b| a.cpm.partial_cmp(&b.cpm).unwrap_or(std::cmp::Ordering::Equal)).map(|r|(r.cpm, r.accuracy)).unwrap_or((0.0,0.0));
    let worst = sessions.iter().min_by(|a,b| a.cpm.partial_cmp(&b.cpm).unwrap_or(std::cmp::Ordering::Equal)).map(|r|(r.cpm, r.accuracy)).unwrap_or((0.0,0.0));
    app.total_best = best; app.total_worst = worst;
    let agg = SessionAggregate { keystrokes, mistakes, duration_ms: current.duration_ms, cpm: avg_cpm, wpm: avg_cpm/5.0, accuracy: avg_acc, score: score_sum, stages_completed: sc, stages_attempted: sa, stages_skipped: skipped };
    app.total_override = Some((agg, total_sessions, sc, sa, 0.0, 0.0));
}

fn open_share(app: &mut App, platform: usize) {
    app.share_platform = Some(platform);
    let url = share_url(app, platform);
    // attempt to open browser
    let result = std::process::Command::new("xdg-open").arg(&url).output();
    let success = matches!(result, Ok(ref o) if o.status.success());
    if success {
        app.share_fallback_url = None;
    } else {
        app.share_fallback_url = Some(url);
    }
}

fn start_game_from_spec(app: &mut App, spec: &str) {
    // transition into game loading (like original starting a new game session)
    log_info("gittype::presentation::cli::commands::game", "Starting GitType game session");
    log_warn("gittype::domain::repositories::version_repository", "Failed to fetch latest version from API: Failed to extract code chunks: Failed to fetch release: error sending request for url (https://api.github.com/repos/unhappychoice/gittype/releases/latest)");
    log_info("gittype::presentation::cli::commands::game", &format!("Initializing all screens with GameData parameters: repo_spec=Some(\"{}\"), repo_path=None", spec));
    // ensure custom theme is created for game
    let _ = ThemeManager::load(true);
    app.repo_spec = Some(spec.to_string());
    app.repo_path_arg = None;
    app.db = None;
    app.challenges.clear();
    app.session = None;
    app.typing = None;
    app.loading_step = 0;
    app.loading_started = Some(Instant::now());
    app.loading_last_advance = Some(Instant::now());
    app.standalone_mode = StandaloneMode::Game;
    app.set_screen(Screen::Loading);
}

fn handle_title_key(app: &mut App, code: KeyCode) {
    match code {
        KeyCode::Right | KeyCode::Char('l') => {
            app.difficulty = app.difficulty.next();
            log_info("gittype::presentation::game::stage_repository", &format!("✅ StageRepository: Difficulty set to {} (keeping cached indices)", app.difficulty.name()));
            app.title_error = None;
        }
        KeyCode::Left | KeyCode::Char('h') => {
            app.difficulty = app.difficulty.prev();
            log_info("gittype::presentation::game::stage_repository", &format!("✅ StageRepository: Difficulty set to {} (keeping cached indices)", app.difficulty.name()));
            app.title_error = None;
        }
        KeyCode::Char('r') | KeyCode::Char('R') => {
            app.records = app.db.as_ref().and_then(|d| load_records_from_db(d).ok()).unwrap_or_default();
            app.records_selected = 0;
            app.set_screen(Screen::Records);
        }
        KeyCode::Char('a') | KeyCode::Char('A') => { app.set_screen(Screen::Analytics); }
        KeyCode::Char('s') | KeyCode::Char('S') => {
            app.settings_tab = 0;
            app.settings_color_idx = if app.theme.current_color_mode == "Light" { 1 } else { 0 };
            app.settings_theme_idx = app.theme.theme_index();
            app.saved_theme_idx = app.settings_theme_idx;
            app.saved_color_mode = app.theme.current_color_mode.clone();
            app.set_screen(Screen::Settings);
        }
        KeyCode::Char('i') | KeyCode::Char('?') => { app.help_tab = 0; app.help_scroll = 0; app.help_github_popup = false; app.set_screen(Screen::Help); }
        KeyCode::Char(' ') => {
            if app.pool().is_empty() {
                app.title_error = Some("No challenges available for this difficulty. Please try a different difficulty or repository.".to_string());
            } else {
                app.title_error = None;
                start_new_session(app);
            }
        }
        KeyCode::Esc => { app.should_quit = true; }
        _ => {}
    }
}

fn handle_settings_key(app: &mut App, code: KeyCode) {
    match code {
        KeyCode::Right | KeyCode::Char('l') | KeyCode::Char('L') => { app.settings_tab = (app.settings_tab + 1) % 2; }
        KeyCode::Left | KeyCode::Char('h') | KeyCode::Char('H') => { app.settings_tab = (app.settings_tab + 1) % 2; }
        KeyCode::Down | KeyCode::Char('j') | KeyCode::Char('J') => {
            if app.settings_tab == 0 { app.settings_color_idx = (app.settings_color_idx + 1).min(1); }
            else { let total = app.theme.themes.len() + 1; app.settings_theme_idx = (app.settings_theme_idx + 1).min(total - 1); }
        }
        KeyCode::Up | KeyCode::Char('k') | KeyCode::Char('K') => {
            if app.settings_tab == 0 { app.settings_color_idx = app.settings_color_idx.saturating_sub(1); }
            else { app.settings_theme_idx = app.settings_theme_idx.saturating_sub(1); }
        }
        KeyCode::Char(' ') => {
            let mode = if app.settings_color_idx == 1 { "Light" } else { "Dark" };
            // apply
            app.theme.current_color_mode = mode.to_string();
            app.theme.current_theme_id = if app.settings_theme_idx >= app.theme.themes.len() { "custom".to_string() } else { app.theme.themes[app.settings_theme_idx].id.clone() };
            let _ = app.theme.save_config(app.settings_theme_idx, mode);
            app.set_screen(Screen::Title);
        }
        KeyCode::Esc => {
            // cancel: theme fields were not changed (preview only)
            app.set_screen(Screen::Title);
        }
        _ => {}
    }
}

fn handle_help_key(app: &mut App, code: KeyCode) {
    if app.help_github_popup {
        if code == KeyCode::Esc { app.help_github_popup = false; }
        return;
    }
    match code {
        KeyCode::Esc => { app.set_screen(Screen::Title); }
        KeyCode::Right | KeyCode::Char('l') | KeyCode::Char('L') => { app.help_tab = (app.help_tab + 1) % 7; app.help_scroll = 0; }
        KeyCode::Left | KeyCode::Char('h') | KeyCode::Char('H') => { app.help_tab = (app.help_tab + 6) % 7; app.help_scroll = 0; }
        KeyCode::Down | KeyCode::Char('j') | KeyCode::Char('J') => { app.help_scroll = app.help_scroll.saturating_add(1); }
        KeyCode::Up | KeyCode::Char('k') | KeyCode::Char('K') => { app.help_scroll = app.help_scroll.saturating_sub(1); }
        KeyCode::Char('g') | KeyCode::Char('G') => {
            // try open browser; in practice fails, show popup
            let _ = std::process::Command::new("xdg-open").arg("https://github.com/unhappychoice/gittype").output();
            app.help_github_popup = true;
        }
        _ => {}
    }
}

fn reload_records(app: &mut App) {
    app.records = app.db.as_ref().and_then(|d| load_records_from_db(d).ok()).unwrap_or_default();
    let len = filtered_sorted_records(app).len();
    if app.records_selected >= len { app.records_selected = len.saturating_sub(1); }
}

fn handle_records_key(app: &mut App, code: KeyCode) {
    match code {
        KeyCode::Esc => { app.set_screen(Screen::Title); }
        KeyCode::Down | KeyCode::Char('j') | KeyCode::Char('J') => {
            let len = filtered_sorted_records(app).len();
            if len > 0 { app.records_selected = (app.records_selected + 1).min(len - 1); }
        }
        KeyCode::Up | KeyCode::Char('k') | KeyCode::Char('K') => { app.records_selected = app.records_selected.saturating_sub(1); }
        KeyCode::Char('f') | KeyCode::Char('F') => { app.records_filter_idx = (app.records_filter_idx + 1) % 4; app.records_selected = 0; }
        KeyCode::Char('s') | KeyCode::Char('S') => { app.records_sort_idx = (app.records_sort_idx + 1) % 8; app.records_selected = 0; }
        KeyCode::Char('r') | KeyCode::Char('R') => { reload_records(app); }
        KeyCode::Char(' ') => {
            let recs = filtered_sorted_records(app);
            if let Some(rec) = recs.get(app.records_selected).cloned() {
                app.selected_record = Some(rec.clone());
                app.records_detail_scroll = 0;
                // load stages
                app.record_detail_stages = Vec::new();
                if let Some(db) = &app.db {
                    if let Ok(rows) = db.query("SELECT st.stage_number, COALESCE(c.file_path,''), COALESCE(c.start_line,0), COALESCE(c.end_line,0), sr.score, sr.cpm, sr.wpm, sr.keystrokes, sr.mistakes, sr.accuracy, sr.duration_ms, sr.was_skipped, sr.was_failed FROM stages st JOIN stage_results sr ON sr.stage_id = st.id LEFT JOIN challenges c ON c.id = st.challenge_id WHERE st.session_id = ? ORDER BY st.stage_number", &[Value::Int(rec.session_id)]) {
                        for r in rows {
                            app.record_detail_stages.push(RecordDetailStage {
                                stage_number: r.int(0).unwrap_or(0), file_path: r.text(1).unwrap_or_default(), start_line: r.int(2).unwrap_or(0), end_line: r.int(3).unwrap_or(0),
                                score: r.real(4).unwrap_or(0.0), cpm: r.real(5).unwrap_or(0.0), wpm: r.real(6).unwrap_or(0.0), keystrokes: r.int(7).unwrap_or(0), mistakes: r.int(8).unwrap_or(0), accuracy: r.real(9).unwrap_or(0.0), duration_ms: r.int(10).unwrap_or(0), was_skipped: r.int(11).unwrap_or(0) != 0, was_failed: r.int(12).unwrap_or(0) != 0,
                            });
                        }
                    }
                }
                app.set_screen(Screen::SessionDetail);
            }
        }
        _ => {}
    }
}

fn handle_typing_key(app: &mut App, code: KeyCode) {
    // options popup first
    let options_open = app.typing.as_ref().map(|t| t.options_open).unwrap_or(false);
    if options_open {
        match code {
            KeyCode::Esc => { if let Some(ts) = &mut app.typing { ts.options_open = false; } }
            KeyCode::Char('s') | KeyCode::Char('S') => {
                // skip
                let can_skip = app.session.as_ref().map(|s| s.skips_remaining > 0).unwrap_or(false);
                if can_skip {
                    let outcome = {
                        let ts = app.typing.as_ref().unwrap();
                        ts.make_outcome(true, false)
                    };
                    if let Some(sess) = &mut app.session { sess.skips_remaining -= 1; sess.outcomes.push(outcome.clone()); }
                    app.last_outcome = Some(outcome);
                    app.set_screen(Screen::StageSummary);
                } else if let Some(ts) = &mut app.typing { ts.options_open = false; }
            }
            KeyCode::Char('q') | KeyCode::Char('Q') => {
                let outcome = {
                    let ts = app.typing.as_ref().unwrap();
                    ts.make_outcome(false, true)
                };
                if let Some(sess) = &mut app.session { sess.outcomes.push(outcome.clone()); }
                app.last_outcome = Some(outcome);
                app.set_screen(Screen::SessionFailure);
            }
            _ => {}
        }
        return;
    }
    // phase handling
    let phase = app.typing.as_ref().map(|t| t.phase);
    match phase {
        Some(TypingPhase::Waiting) => {
            match code {
                KeyCode::Char(' ') => {
                    if let Some(ts) = &mut app.typing { ts.phase = TypingPhase::Countdown; ts.countdown_start = Some(Instant::now()); }
                }
                KeyCode::Esc => { if let Some(ts) = &mut app.typing { ts.options_open = true; } }
                _ => {}
            }
        }
        Some(TypingPhase::Countdown) => {
            if code == KeyCode::Esc { if let Some(ts) = &mut app.typing { ts.options_open = true; } }
        }
        Some(TypingPhase::Active) => {
            match code {
                KeyCode::Esc => { if let Some(ts) = &mut app.typing { ts.options_open = true; } }
                KeyCode::Enter => { typing_input(app, '\n'); }
                KeyCode::Backspace => {
                    if let Some(ts) = &mut app.typing {
                        if ts.pos > 0 {
                            ts.pos -= 1;
                            // step back over auto indent? if we landed in indent region, keep stepping to newline or non-indent
                            while ts.pos > 0 {
                                let prev = ts.target[ts.pos - 1];
                                let cur = ts.target[ts.pos];
                                if (cur == ' ' || cur == '\t') && prev == '\n' { ts.pos -= 1; } else { break; }
                            }
                            if ts.current_streak > 0 { ts.current_streak -= 1; }
                        }
                    }
                }
                KeyCode::Char(c) => {
                    if c == '\n' || c == '\r' { typing_input(app, '\n'); } else { typing_input(app, c); }
                }
                _ => {}
            }
        }
        None => {}
    }
    // completion check
    let completed = app.typing.as_ref().map(|ts| ts.phase == TypingPhase::Active && ts.pos >= ts.target.len()).unwrap_or(false);
    if completed {
        let outcome = {
            let ts = app.typing.as_ref().unwrap();
            ts.make_outcome(false, false)
        };
        if let Some(sess) = &mut app.session { sess.outcomes.push(outcome.clone()); }
        app.last_outcome = Some(outcome);
        app.set_screen(Screen::StageSummary);
    }
}

fn typing_input(app: &mut App, input: char) {
    if let Some(ts) = &mut app.typing {
        if ts.pos >= ts.target.len() { return; }
        let expected = ts.target[ts.pos];
        ts.keystrokes += 1;
        if input == expected {
            ts.pos += 1;
            ts.current_streak += 1;
            ts.last_mistake_pos = None;
            ts.skip_indent();
        } else {
            ts.mistakes += 1;
            ts.last_mistake_pos = Some(ts.pos);
            if ts.current_streak > 0 { ts.streaks.push(ts.current_streak); }
            ts.current_streak = 0;
        }
    }
}
