fn set_total_override_from_result(app: &mut App) {
    // DB aggregates plus duplicate current session (as observed)
    let current = session_aggregate_for_summary(app);
    let db_records = app.db.as_ref().and_then(|d| load_records_from_db(d).ok()).unwrap_or_default();
    let mut sessions = db_records.clone();
    // add duplicate of current session as an extra record-like entry for totals
    // Instead compute directly
    let total_sessions = sessions.len() + 1;
    let mut keystrokes: i64 = 0; let mut mistakes: i64 = 0; let mut skipped: i64 = 0; let mut sc: i64 = 0; let mut sa: i64 = 0; let mut score_sum = 0.0;
    let mut cpm_sum = 0.0; let mut acc_sum = 0.0;
    if let Some(db) = &app.db {
        if let Ok(rows) = db.query("SELECT SUM(keystrokes), SUM(mistakes), SUM(stages_skipped), SUM(stages_completed), SUM(stages_attempted), SUM(score), SUM(cpm), SUM(accuracy) FROM session_results", &[]) {
            if let Some(r) = rows.get(0) {
                keystrokes = r.int(0).unwrap_or(0); mistakes = r.int(1).unwrap_or(0); skipped = r.int(2).unwrap_or(0); sc = r.int(3).unwrap_or(0); sa = r.int(4).unwrap_or(0); score_sum = r.real(5).unwrap_or(0.0); cpm_sum = r.real(6).unwrap_or(0.0); acc_sum = r.real(7).unwrap_or(0.0);
            }
        }
    }
    // duplicate current
    keystrokes += current.keystrokes; mistakes += current.mistakes; skipped += current.stages_skipped; sc += current.stages_completed; sa += current.stages_attempted; score_sum += current.score; cpm_sum += current.cpm; acc_sum += current.accuracy;
    sessions.push(RecordItem { session_result_id: 0, session_id: 0, repository_id: 0, started_at: String::new(), repo_display: String::new(), score: current.score, cpm: current.cpm, wpm: current.wpm, accuracy: current.accuracy, stages_completed: current.stages_completed, stages_attempted: current.stages_attempted, duration_ms: current.duration_ms, branch: None, commit_hash: None });
    let avg_cpm = if total_sessions>0 { cpm_sum / total_sessions as f64 } else {0.0};
    let avg_acc = if total_sessions>0 { acc_sum / total_sessions as f64 } else {0.0};
    let best = sessions.iter().max_by(|a,b| a.cpm.partial_cmp(&b.cpm).unwrap_or(std::cmp::Ordering::Equal)).map(|r|(r.cpm, r.accuracy)).unwrap_or((0.0,0.0));
    let worst = sessions.iter().min_by(|a,b| a.cpm.partial_cmp(&b.cpm).unwrap_or(std::cmp::Ordering::Equal)).map(|r|(r.cpm, r.accuracy)).unwrap_or((0.0,0.0));
    app.total_best = best; app.total_worst = worst;
    let agg = SessionAggregate { keystrokes, mistakes, duration_ms: current.duration_ms, cpm: avg_cpm, wpm: avg_cpm/5.0, accuracy: avg_acc, score: score_sum, stages_completed: sc, stages_attempted: sa, stages_skipped: skipped };
    app.total_override = Some((agg, total_sessions, sc, sa, 0.0, 0.0));
}

