        // manual character wrapping matching original (long URL fills each line)
        {
            let full = format!("  📋 {}", url);
            let maxw = area.width as usize;
            let mut chunks: Vec<String> = Vec::new();
            let mut cur = String::new();
            let mut curw = 0usize;
            for ch in full.chars() {
                let w = unicode_width::UnicodeWidthChar::width(ch).unwrap_or(0);
                if curw + w > maxw && curw > 0 { chunks.push(cur); cur = String::new(); curw = 0; }
                cur.push(ch); curw += w;
            }
            if !cur.is_empty() { chunks.push(cur); }
            for (i, chunk) in chunks.iter().enumerate() {
                f.render_widget(Paragraph::new(Line::from(Span::styled(chunk.clone(), s_rgb(pal.status_info)))), Rect::new(area.x, url_y + i as u16, area.width, 1));
            }
            let bottom_y = url_y + chunks.len() as u16;
            let bottom = vec![
                Line::from(""),
                Line::from(Span::styled("💡 Tip: Select and copy the URL with your mouse or keyboard", s_rgb(pal.text))),
                Line::from(""),
                Line::from(vec![key_span(&pal, "back", "[ESC]"), Span::styled(" Back", s_rgb(pal.text))]),
            ];
            f.render_widget(Paragraph::new(bottom).alignment(Alignment::Center), Rect::new(area.x, bottom_y + 1, area.width, 4));
            return;
        }'''
